INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (1, 'Activities of Daily Living', '일상생활활동 기능사정', 'ADL', '기본적인 일상 자가 간호 활동(식사, 옷 입기 등)의 수행 능력 및 그 평가.'),
                                                                         (2, 'Acute Respiratory Distress Syndrome', '급성호흡곤란증후군', 'ARDS', '폐의 심한 염증 및 폐포 손상으로 급격한 호흡곤란을 유발하는 중증 폐 상태.'),
                                                                         (3, 'Akinesia', '운동불능', NULL, '움직임을 시작하거나 수행하는 능력이 상실 또는 저하된 상태. (예: 파킨슨병)'),
                                                                         (4, 'Alert', '명료', NULL, '환자가 깨어 있으며, 주변 환경과 자극에 정상적으로 반응하는 의식 상태.'),
                                                                         (5, 'Alzheimer\'s disease', '알츠하이머 병', NULL, '기억력, 사고력, 행동 등에 문제를 일으키는 가장 흔한 유형의 진행성 뇌 질환 치매.'),
  (6, 'Amyotrophic lateral sclerosis', '루게릭병(근위축성측삭경화증)', NULL, '운동 신경 세포가 점진적으로 파괴되어 근육 약화, 마비 등을 유발하는 신경계 질환.'),
  (7, 'Aphasia', '실어증', NULL, '뇌 손상으로 인해 언어 이해나 표현 능력(말하기, 듣기, 읽기, 쓰기)이 저하 또는 상실된 상태.'),
  (8, 'Apraxia', '행동불능증', NULL, '운동 기능은 정상이지만 특정 목적의 행동을 수행하지 못하는 신경학적 장애.'),
  (9, 'Arrhythmia', '부정맥', NULL, '심장 박동이 비정상적으로 빠르거나, 느리거나, 불규칙한 상태.'),
  (10, 'Arthralgia', '관절통', NULL, '관절 부위에 발생하는 통증. 염증을 동반하지 않을 수 있음.'),
  (11, 'Arthritis', '관절염', NULL, '하나 이상의 관절에 염증이 발생하여 통증, 부기, 뻣뻣함 등을 유발하는 질환.'),
  (12, 'Aspiration pneumonia', '흡인성 폐렴', NULL, '음식물, 침 등이 기도로 넘어가 폐에 염증을 일으키는 폐렴. 연하곤란 환자에게 위험.'),
  (13, 'Asthma', '천식', NULL, '특정 자극에 의해 기도가 좁아져 호흡곤란, 기침, 천명음 등이 반복되는 만성 기도 염증 질환.'),
  (14, 'Atelectasis', '무기폐', NULL, '폐의 일부 또는 전체가 제대로 팽창하지 못하고 쪼그라든 상태.'),
  (15, 'Atrophy', '위축', NULL, '세포, 조직, 기관 등의 크기가 정상보다 작아지거나 기능이 저하되는 현상.'),
  (16, 'Avascular Necrosis', '무혈관성괴사', 'AVN', '뼈 조직으로의 혈액 공급 차단으로 뼈 세포가 죽는 질환. (주로 고관절 발생)'),
  (17, 'Benign Prostatic Hypertrophy', '전립선비대증', 'BPH', '전립선 비대로 요도를 압박하여 배뇨곤란, 빈뇨 등을 유발하는 남성 노인에게 흔한 질환.'),
  (18, 'Blepharoptosis', '안검하수', NULL, '윗눈꺼풀이 아래로 처져 시야를 가리거나 외관상 문제를 일으키는 상태.'),
  (19, 'Bowel incontinence', '변실금', NULL, '대변 조절 능력 상실로 의지와 관계없이 대변이 배출되는 상태.'),
  (20, 'Catalepsy', '강직증', NULL, '신체가 뻣뻣하게 굳어 특정 자세를 유지하며 외부 자극에 반응이 없는 상태.'),
  (21, 'Cerebral infarction', '뇌졸중', NULL, '뇌혈관이 막혀 뇌 조직에 혈액 공급이 중단되어 뇌세포가 손상되는 질환. (제공된 설명은 허혈성에 가까움)'),
  (22, 'Chronic Obstructive Pulmonary Disease', '만성폐쇄성폐질환', 'COPD', '유해 가스 흡입(주로 흡연)으로 인한 만성 폐 염증 및 기도 협착으로 호흡곤란을 유발하는 진행성 폐 질환.'),
  (23, 'Chronic Renal Failure', '만성신부전', NULL, '신장 기능이 점진적으로 악화되어 노폐물 배설 및 체액 균형 조절 능력이 상실되는 상태.'),
  (24, 'Coma', '혼수', NULL, '외부 자극에 전혀 반응하지 못하고 깨울 수 없는 심각한 의식 불명 상태.'),
  (25, 'Congestive Heart Failure', '울혈성 심부전', 'CHF', '심장 펌프 기능 저하로 신체에 혈액 공급이 불충분하고 폐나 전신에 체액이 축적되는 상태.'),
  (26, 'Deep Vein Thrombosis', '심부정맥혈전증', 'DVT', '주로 다리 깊은 정맥에 혈전(피떡)이 생기는 질환. 폐색전증 유발 가능.'),
  (27, 'Degenerative arthritis', '퇴행성 관절염', NULL, '관절 연골이 점차 마모되어 관절 통증과 변형을 유발하는 가장 흔한 관절 질환. (골관절염과 유사)'),
  (28, 'Delusion', '망상', NULL, '사실과 다른 잘못된 믿음을 견고하게 고수하며 교정되지 않는 사고 장애.'),
  (29, 'Dementia', '치매', NULL, '기억력, 사고력 등 인지 기능이 점진적으로 저하되어 일상생활에 어려움을 겪는 뇌 질환군.'),
  (30, 'Depression', '우울', NULL, '슬픔, 절망감, 흥미 상실 등이 지속되어 일상 기능에 영향을 미치는 기분 장애.'),
  (31, 'Diabetic neuropathy', '당뇨병성 말초신경병증', NULL, '당뇨병 합병증으로 말초 신경이 손상되어 손발 저림, 통증, 감각 저하 등을 유발하는 질환.'),
  (32, 'Diabetic retinopathy', '당뇨망막병증', NULL, '당뇨병으로 인해 망막 미세 혈관이 손상되어 시력 저하 및 실명을 유발할 수 있는 눈 합병증.'),
  (33, 'Diplopia', '복시', NULL, '하나의 물체가 두 개로 보이거나 겹쳐 보이는 시각 증상.'),
  (34, 'Drowsy', '기면', NULL, '졸리고 잠이 오는 상태로, 자극에 대한 반응이 느려지는 의식 수준 저하 상태.'),
  (35, 'Dysarthria', '구음장애', NULL, '발음에 필요한 근육 문제로 발음이 불분명해지는 언어 장애.'),
  (36, 'Dyskinesia', '운동이상증', NULL, '불수의적이고 비정상적인 움직임(꿈틀거림, 뒤틀림 등)이 나타나는 상태.'),
  (37, 'Dysphagia', '연하곤란', NULL, '음식물이나 액체를 삼키기 어렵거나 삼킬 때 통증을 느끼는 증상.'),
  (38, 'Dysuria', '배뇨곤란', NULL, '소변을 볼 때 통증이나 불편감을 느끼는 증상.'),
  (39, 'Epiglottitis', '후두개염', NULL, '후두덮개(음식물의 기도 유입 방지 연골)의 염증으로, 심하면 기도 폐쇄 유발.'),
  (40, 'Fall down', '낙상', NULL, '의도치 않게 넘어지거나 떨어지는 사고. 노인에게 심각한 손상 유발 가능.'),
  (41, 'Fecal impaction', '분변매복', NULL, '단단한 대변 덩어리가 직장이나 결장에 정체되어 배출되지 못하는 상태.'),
  (42, 'Frost bite', '동상', NULL, '심한 추위 노출로 피부 및 피하 조직이 얼어 손상되는 상태.'),
  (43, 'Frozen Shoulder', '오십견', NULL, '어깨 관절 주변 조직의 염증 및 유착으로 통증과 운동 제한이 발생하는 질환.'),
  (44, 'Gastric ulcer', '위궤양', NULL, '위 점막이 손상되어 움푹 패인 상태. 속쓰림, 복통 등 유발.'),
  (45, 'Gastroesophageal reflux disease', '위식도역류질환', 'GERD', '위산이나 위 내용물이 식도로 역류하여 가슴쓰림, 신물 등의 증상을 유발하는 질환.'),
  (46, 'Glasgow Coma Scale', '글라스고 혼수척도', 'GCS', '눈 뜨기, 언어 반응, 운동 반응을 점수화하여 환자의 의식 수준을 평가하는 표준 도구.'),
  (47, 'Glaucoma', '녹내장', NULL, '시신경 손상으로 시야가 점차 좁아져 실명에 이를 수 있는 안과 질환. 주로 안압 상승과 관련.'),
  (48, 'Gout', '통풍', NULL, '혈액 내 요산 수치 상승으로 요산 결정이 관절 등에 쌓여 급성 염증과 통증을 유발하는 대사성 질환.'),
  (49, 'Hallucination', '환각', NULL, '외부 자극 없이 실제처럼 지각하는 현상 (헛것이 보이거나 헛소리가 들림 등).'),
  (50, 'Hematuria', '혈뇨', NULL, '소변에 비정상적으로 적혈구가 섞여 나오는 상태.'),
  (51, 'Hemiparesis', '편측마비', NULL, '신체의 왼쪽 또는 오른쪽 절반에 근력 약화가 나타나는 상태.'),
  (52, 'Hemiplegia', '반신불수', NULL, '신체의 왼쪽 또는 오른쪽 절반이 완전히 마비된 상태.'),
  (53, 'Hoarseness', '목이 쉼', NULL, '목소리가 거칠거나 쉬어 정상적인 소리를 내기 어려운 상태.'),
  (54, 'Hyperlipidemia', '고지혈증', NULL, '혈액 내 콜레스테롤이나 중성지방 수치가 정상보다 높은 상태. 동맥경화 위험 요인.'),
  (55, 'Hypertonia', '강직', NULL, '근육 긴장도가 비정상적으로 증가하여 뻣뻣해지고 움직임이 어려운 상태.'),
  (56, 'Immobility', '부동', NULL, '신체적 움직임이 없거나 매우 제한된 상태. 욕창, 근위축 등 합병증 유발 가능.'),
  (57, 'Incontinence', '요실금', NULL, '자신의 의지와 관계없이 소변이 배출되는 증상.'),
  (58, 'Intraocular Pressure', '안압', NULL, '눈 내부의 압력. 정상 범위 유지가 눈 건강 및 녹내장과 관련.'),
  (59, 'keratosis', '각화증', NULL, '피부 각질층이 비정상적으로 두꺼워지는 상태를 통칭. (예: 광선각화증)'),
  (60, 'Level Of Conscious', '의식수준', 'LOC', '자신과 주변 환경을 인지하고 반응하는 정도를 나타내는 지표. (명료, 기면, 혼미, 반혼수, 혼수 등)'),
  (61, 'Lung Cancer', '폐암', 'LC', '폐에서 발생하는 악성 종양. 초기 증상이 없어 진단이 늦어질 수 있음.'),
  (62, 'Macula Degeneration', '황반변성', NULL, '망막 중심부 황반 조직 손상으로 중심 시력 저하 및 사물 왜곡을 유발하는 안과 질환.'),
  (63, 'Mask like face', '표정없는 얼굴', NULL, '얼굴 근육 경직으로 감정 표현이 없는, 가면을 쓴 듯한 무표정한 얼굴. (예: 파킨슨병)'),
  (64, 'Metabolic syndrome', '대사증후군', NULL, '복부비만, 고혈압, 고혈당 등 5가지 중 3가지 이상이 함께 나타나는 상태. 심뇌혈관질환 위험 증가.'),
  (65, 'Multiple Sclerosis', '다발성 경화증', NULL, '중추신경계(뇌, 척수, 시신경)에 염증과 손상이 반복되는 만성 자가면역질환.'),
  (66, 'Myasthenia Gravis', '중증성 근무력증', NULL, '신경-근육 신호 전달 장애로 근육이 쉽게 피로해지고 약해지는 만성 자가면역질환.'),
  (67, 'Nystagmus', '안구진탕증', NULL, '의지와 관계없이 눈알이 규칙적 또는 불규칙적으로 떨리는 증상.'),
  (68, 'Orientation', '지남력', NULL, '현재 시간, 장소, 사람에 대한 인지 능력. 의식 및 인지 기능 평가에 사용.'),
  (69, 'Osteoarthritis', '골관절염', NULL, '관절 연골 마모 및 손상으로 관절 통증, 뻣뻣함, 운동 제한 등을 유발하는 퇴행성 관절 질환.'),
  (70, 'Osteoporosis', '골다공증', NULL, '뼈의 양 감소 및 질 약화로 작은 충격에도 골절되기 쉬운 상태.'),
  (71, 'Pacemaker', '심박조율기', NULL, '심장 박동이 느리거나 불규칙할 때 정상 박동 유지를 위해 전기 자극을 보내는 의료 기기.'),
  (72, 'Paresthesia', '지각이상', NULL, '실제 자극 없이 저림, 따끔거림, 화끈거림 등 비정상적인 감각을 느끼는 증상.'),
  (73, 'Parkinson\'s disease', '파킨슨병', NULL, '뇌 도파민 분비 신경 세포 손상으로 안정 시 떨림, 경직, 운동 느림 등을 특징으로 하는 진행성 신경퇴행성 질환.'),
                                                                         (74, 'Peripheral neurovascular dysfunction', '말초신경혈관기능장애', NULL, '팔다리 등 말초 부위의 신경 및 혈관 기능 이상 상태를 포괄적으로 지칭.'),
                                                                         (75, 'Physical therapy', '물리치료', NULL, '통증 완화, 기능 회복, 운동 능력 향상을 위해 열, 냉기, 전기, 도수 치료 등을 이용하는 치료.'),
                                                                         (76, 'Pneumonia', '폐렴', NULL, '세균, 바이러스, 곰팡이 등의 감염으로 폐 조직에 염증이 발생하는 질환.'),
                                                                         (77, 'Polydipsia', '다갈', NULL, '비정상적으로 심한 갈증을 느껴 물을 많이 마시는 증상. (예: 당뇨병)'),
                                                                         (78, 'Polyneuritis', '다발성 신경염', NULL, '여러 말초 신경에 동시에 염증이나 손상이 발생하여 감각 이상, 근력 약화 등을 유발하는 상태.'),
                                                                         (79, 'Polyphagia', '다식증', NULL, '비정상적으로 식욕이 항진되어 음식을 많이 먹는 증상. (예: 당뇨병)'),
                                                                         (80, 'Polyuria', '다뇨', NULL, '소변량이 비정상적으로 증가하여 소변을 자주, 많이 보는 증상. (예: 당뇨병)'),
                                                                         (81, 'Presbycusis', '노인성난청', NULL, '노화로 인해 청력이 점진적으로 저하되는 현상. 특히 고음역대 청취 어려움.'),
                                                                         (82, 'Presbyopia', '노안', NULL, '수정체 탄력성 저하로 가까운 물체에 초점 맞추기가 어려워지는 시력 변화.'),
                                                                         (83, 'Pulmonary Tuberculosis', '폐결핵', 'TB,Tbc', '결핵균 감염으로 폐에 발생하는 만성 감염성 질환.'),
                                                                         (84, 'Quadriplegia', '사지마비', NULL, '목 부위 척수 손상 등으로 팔, 다리, 몸통 전체에 마비가 온 상태.'),
                                                                         (85, 'Range of Motion', '관절가동범위', 'ROM', '각 관절이 정상적으로 움직일 수 있는 최대한의 각도나 범위.'),
                                                                         (86, 'Rheumatoid Arthritis', '류마티스성 관절염', 'RA', '관절 활막의 만성 염증을 특징으로 하는 자가면역질환. 관절 변형 및 기능 장애 유발.'),
                                                                         (87, 'Rhonchi', '수포음', NULL, '기도가 부분적으로 막혔을 때 나는 낮고 거친 연속적인 호흡음. (일반적 \'악설음\'과 구분)'),
                                                                         (88, 'Semicoma', '반혼수', NULL, '강한 자극에만 약간 반응하는 깊은 의식 저하 상태. 혼수보다 얕은 단계.'),
                                                                         (89, 'Senescence', '노쇠', NULL, '노화로 신체적, 정신적 기능이 전반적으로 저하되고 질병과 스트레스에 취약해진 상태.'),
                                                                         (90, 'Senile Cataract', '노인성 백내장', NULL, '노화로 눈의 수정체가 혼탁해져 시력이 점차 저하되는 질환.'),
                                                                         (91, 'Senile spot', '노인성 반점', NULL, '노화로 햇볕 노출 피부에 나타나는 갈색 또는 검은색의 편평한 반점.'),
                                                                         (92, 'Sensory neural hearing loss', '감각신경성 난청', 'SNHL', '내이(달팽이관)의 감각 세포나 청신경 손상으로 발생하는 난청.'),
                                                                         (93, 'Skin integrity', '피부 통합성', NULL, '피부가 손상 없이 건강하고 정상적인 구조와 기능을 유지하는 상태.'),
                                                                         (94, 'Sleep disturbance', '수면장애', NULL, '정상적인 수면 유지의 어려움 또는 수면의 질 저하로 일상생활에 영향을 미치는 상태.'),
                                                                         (95, 'Sleep apnea', '수면 무호흡증', NULL, '수면 중 호흡이 일시적으로 반복해서 멈추거나 감소하는 상태.'),
                                                                         (96, 'Spinal Stenosis', '척추관 협착증', NULL, '척추관이나 신경근관이 좁아져 신경을 압박, 허리 통증 및 다리 저림 등을 유발하는 질환.'),
                                                                         (97, 'Stroke', '뇌졸중', NULL, '뇌혈관 문제(막힘 또는 터짐)로 뇌 기능이 손상되어 신경학적 증상을 유발하는 질환.'),
                                                                         (98, 'Stupor', '혼미', NULL, '강한 통증 자극에만 겨우 반응하고 자발적 움직임이 거의 없는 심각한 의식 저하 상태.'),
                                                                         (99, 'Tardive Dyskinesia', '지연성 운동장애', NULL, '주로 항정신병 약물 장기 사용 후 나타날 수 있는 불수의적, 반복적 운동 장애. (예: 입맛 다시기)'),
                                                                         (100, 'Thrombocytopenia', '혈소판 감소증', NULL, '혈액 내 혈소판 수가 정상보다 감소하여 출혈 경향이 높아지는 상태.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (101, 'Thromboembolism', '색전증', NULL, '혈전 등이 혈관을 따라 이동하다 다른 부위 혈관을 막는 질환 상태 또는 그 혈전 조각.'),
                                                                         (102, 'Thrombophlebitis', '혈전성 정맥염', NULL, '정맥에 혈전이 생기고 염증이 동반된 상태.'),
                                                                         (103, 'Tinnitus', '이명', NULL, '외부 소리 자극 없이 귀나 머릿속에서 소리가 들린다고 느끼는 증상. (예: 윙윙, 삐 소리)'),
                                                                         (104, 'Total Hip Replacement Arthroplasty', '전고관절치환관절성형술', 'THRA', '손상된 고관절(엉덩관절) 전체를 인공 관절로 교체하는 수술.'),
                                                                         (105, 'Transient Ischemic Attacks', '일과성 허혈 발작', 'TIAs', '뇌 혈류의 일시적 차단 후 회복으로 나타나는 일시적 뇌졸중 유사 증상. \'미니 뇌졸중\'.'),
                                                                         (106, 'Varicose Vein', '정맥류', NULL, '정맥 판막 기능 이상으로 혈액이 역류, 정체되어 정맥이 늘어나고 꼬불꼬불해지는 질환.'),
                                                                         (107, 'Vertigo', '현기증', NULL, '자신이나 주변 환경이 움직이거나 회전하는 듯한 느낌을 받는 어지럼증의 한 종류.'),
                                                                         (108, 'Wheezing', '천명음', NULL, '좁아진 기도를 공기가 통과할 때 나는 \'쌕쌕\' 또는 \'휘이\' 거리는 높은 톤의 호흡음. (예: 천식)'),
                                                                         (109, 'withdrawal', '금단', NULL, '특정 물질(알코올, 약물 등) 사용 중단/감량 시 나타나는 불쾌한 신체적, 정신적 증상군.'),
                                                                         (110, 'Xerosis', '건조증', NULL, '피부, 점막 등이 비정상적으로 건조한 상태.'),
                                                                         (111, 'Acute otitis media', '급성 중이염', NULL, '중이(귀의 중간 공간)에 발생하는 급성 염증. 귀 통증, 발열 등 동반.'),
                                                                         (112, 'Acute pancreatitis', '급성췌장염', NULL, '다양한 원인으로 췌장 세포가 손상되어 췌장에 염증이 생기는 질환.'),
                                                                         (113, 'Acute sinusitis', '급성부비동염', NULL, '코 주변 빈 공간인 부비동에 염증이 생겨 콧물, 코막힘 등을 유발하는 상태.'),
                                                                         (114, 'Alert', '명료', NULL, '환자가 깨어 있으며, 주변 환경과 자극에 정상적으로 반응하는 의식 상태.'),
                                                                         (115, 'Amputation', '절단', NULL, '질병이나 외상으로 인해 신체의 일부(주로 팔, 다리)를 외과적으로 제거하는 것입니다.'),
                                                                         (116, 'Angina pectoris', '협심증', NULL, '관상동맥이 좁아져 심장 근육에 산소 공급이 부족해지면서 발생하는 가슴 통증입니다.'),
                                                                         (117, 'Aortic aneurysm', '대동맥류', NULL, '대동맥 벽이 약해져 풍선처럼 부풀어 직경이 1.5배 이상 커진 상태.'),
                                                                         (118, 'Abdominal aortic aneurysm', '복부대동맥류', 'AAA', '복부 대동맥이 비정상적으로 늘어나 부풀어 오르는 질환.'),
                                                                         (119, 'appendicitis', '충수염', NULL, '충수(맹장 끝부분)에 발생하는 염증 및 감염.'),
                                                                         (120, 'Artificial airway', '인공기도', NULL, '호흡을 유지하기 위해 사용하는 인공적인 기도 확보 수단.'),
                                                                         (121, 'Asphyxia', '질식', NULL, '신체 조직에 산소 공급이 정상적으로 이루어지지 않는 상태. (기도 막힘 등)'),
                                                                         (122, 'Asystole', '무수축', NULL, '심장의 수축 기능이 중단되거나 극도로 약해진 상태.'),
                                                                         (123, 'Burn', '화상', NULL, '열, 화학물질, 전기, 방사선 등에 의해 피부 및 조직이 손상된 상태.'),
                                                                         (124, 'Cardiac arrest', '심정지', NULL, '심장 기능이 갑자기 정지하여 혈액 순환이 멈춘 상태.'),
                                                                         (125, 'Cardiac tamponade', '심장눌림증', NULL, '심낭 내 체액 축적 등으로 심장이 압박되어 혈액을 제대로 채우거나 박출하지 못하는 상태.'),
                                                                         (126, 'Cardioversion', '부정맥 치료', NULL, '비정상적인 심장 박동을 정상화하거나 조절하기 위한 시술 또는 치료.'),
                                                                         (127, 'Cerebral hemorrhage', '뇌출혈', NULL, '뇌혈관이 터져 뇌 안에 출혈이 발생하여 뇌 조직을 손상시키는 질환.'),
                                                                         (128, 'intracranial hemorrhage', '뇌내출혈', 'ICH', '뇌 조직 안의 혈관이 터져 발생하는 출혈. 자발성 또는 외상성으로 구분.'),
                                                                         (129, 'Choking', '숨막힘', NULL, '기도가 막히거나 좁아져 호흡이 어려운 상태.'),
                                                                         (130, 'Cholecystitis', '담낭염', NULL, '담낭(쓸개)에 발생하는 염증.'),
                                                                         (131, 'Cholelithiasis', '담석증', NULL, '담낭 또는 담관에 결석(돌)이 생성된 질환.'),
                                                                         (132, 'Coma', '혼수', NULL, '어떤 자극에도 반응이 없는 깊은 의식 불명 상태. (위의 혼수와 중복되나, 강조를 위해 유지)'),
                                                                         (133, 'Concussion', '뇌진탕', NULL, '머리 충격으로 인한 일시적인 뇌 기능 장애. 의식 소실이 동반될 수 있음.'),
                                                                         (134, 'Confusion', '혼란 , 혼동', NULL, '생각이나 상황 판단이 불분명하고 뒤섞인 정신 상태.'),
                                                                         (135, 'Convulsion', '경련 , 경기', NULL, '근육이 불수의적으로 갑작스럽게 수축하는 발작적 증상.'),
                                                                         (136, 'Debridement', '변연절제술', NULL, '손상되거나 감염된 조직, 또는 괴사 조직을 수술적으로 제거하는 시술.'),
                                                                         (137, 'Defibrillation', '제세동', NULL, '심실세동 등 치명적 부정맥 발생 시 전기 충격을 가해 심장 박동을 정상화하는 응급 시술.'),
                                                                         (138, 'Dizziness', '현기증', NULL, '어지럼증을 통칭하는 용어. (아래 Vertigo와 구분될 수 있음)'),
                                                                         (139, 'vertigo', '현기증', NULL, '자신이나 주변이 회전하는 듯한 느낌의 특정 어지럼증. (위 Dizziness와 중복이나, 구체적 의미로 유지)'),
                                                                         (140, 'Drowsy', '졸림 , 나른함', NULL, '잠이 오거나 몸에 힘이 없고 늘어지는 느낌의 상태.'),
                                                                         (141, 'eclampsia', '자간증', NULL, '임신 중 고혈압과 함께 경련 발작이 발생하는 심각한 합병증.'),
                                                                         (142, 'ectopic pregnancy', '자궁 외 임신', NULL, '수정란이 자궁 내막이 아닌 다른 곳(주로 난관)에 착상한 임신.'),
                                                                         (143, 'peritonitis', '복막염', NULL, '복강을 덮는 얇은 막인 복막에 발생하는 염증.'),
                                                                         (144, 'endotracheal intubation', '기관 내 삽관', NULL, '기도 확보를 위해 입이나 코를 통해 기관 내로 튜브를 삽입하는 시술.'),
                                                                         (145, 'epididymitis', '부고환염', NULL, '고환 옆에 위치한 부고환에 발생하는 염증.'),
                                                                         (146, 'epidural hematoma', '경막 외 혈종', NULL, '두개골과 뇌 경막 사이 공간에 혈액이 고인 상태. 주로 외상으로 발생.'),
                                                                         (147, 'epiglottitis', '후두개염', NULL, '후두덮개에 염증이 생겨 기도를 막을 수 있는 응급 질환. (위의 후두개염과 중복, 강조)'),
                                                                         (148, 'epilepsy', '간질', NULL, '뇌 신경 세포의 비정상적 전기 흥분으로 인해 반복적인 발작을 특징으로 하는 신경계 질환.'),
                                                                         (149, 'epistaxis', '코피 , 비출혈', NULL, '코에서 피가 나는 증상.'),
                                                                         (150, 'esophageal varix bleeding', '식도정맥류', NULL, '주로 간경변증 등으로 문맥압이 상승하여 식도 정맥이 부풀어 오르는 질환. 출혈 위험.'),
                                                                         (151, 'fall down', '떨어지다', NULL, '높은 곳에서 떨어지거나 넘어져 다치는 사고. (낙상과 의미 유사)'),
                                                                         (152, 'flail chest', '흉곽동요', NULL, '다발성 늑골 골절 등으로 흉벽 일부가 호흡 시 역설적으로 움직이는 불안정한 상태.'),
                                                                         (153, 'gastric lavage', '위세척', NULL, '독극물 섭취 등 응급 상황에서 위 내용물을 제거하기 위해 관을 삽입하여 세척하는 시술.'),
                                                                         (154, 'gross hematuria', '육안적 혈뇨', NULL, '소변에 피가 섞여 나와 눈으로 붉게 보이는 상태.'),
                                                                         (155, 'hematemesis', '토혈', NULL, '식도, 위, 십이지장 등 상부 위장관 출혈로 인해 피를 토하는 증상.'),
                                                                         (156, 'hematochezia', '혈변배설', NULL, '대변에 피가 섞여 나오는 증상. 출혈 위치에 따라 색이 다름.'),
                                                                         (157, 'hemophilia', '혈우병', NULL, '혈액 응고 인자 부족으로 출혈 시 피가 잘 멎지 않는 유전 질환.'),
                                                                         (158, 'hemoptysis', '객혈', NULL, '기관지나 폐 등 하부 호흡기에서 발생한 출혈이 기침과 함께 배출되는 증상.'),
                                                                         (159, 'hemorrhage', '출혈', NULL, '혈액이 혈관 밖으로 나오는 현상.'),
                                                                         (160, 'hemothorax', '혈흉', NULL, '흉강(가슴 안 공간) 내에 혈액이 고인 상태.'),
                                                                         (161, 'hypertensive crisis', '고혈압 위기', NULL, '혈압이 매우 심각한 수준으로 급격히 상승하여 즉각적인 조치가 필요한 응급 상태.'),
                                                                         (162, 'hyperthermia', '고체온', NULL, '체온이 비정상적으로 높은 상태. (예: 열사병)'),
                                                                         (163, 'hyphema', '전방출혈', NULL, '눈의 각막과 홍채 사이 공간(전방)에 혈액이 고인 상태. 주로 외상으로 발생.'),
                                                                         (164, 'hypothermia', '저체온', NULL, '체온이 비정상적으로 낮은 상태.'),
                                                                         (165, 'hypoglycemia', '저혈당증', NULL, '혈액 내 포도당 농도가 정상 수치보다 낮은 상태.'),
                                                                         (166, 'laceration', '열상', NULL, '피부나 조직이 외부 힘에 의해 찢어져 생긴 상처.'),
                                                                         (167, 'laryngoscope', '후두경', NULL, '후두 및 주변 구조를 관찰하거나 시술 시 사용하는 의료 기구.'),
                                                                         (168, 'mechanical ventilation', '기계적 환기', NULL, '자발 호흡이 불가능하거나 부족할 때 기계 장치를 이용해 인공적으로 호흡을 보조하거나 대체하는 치료.'),
                                                                         (169, 'melena', '흑색변', NULL, '상부 위장관 출혈로 인해 혈액이 위산과 반응하여 변색된, 타르처럼 검고 끈적한 변.'),
                                                                         (170, 'multiple trauma', '다발성외상', NULL, '신체 여러 부위에 동시에 발생한 복합적인 손상.'),
                                                                         (171, 'neurologic examination', '신경학적검사', NULL, '뇌, 척수, 말초신경 및 근육의 기능 이상을 평가하기 위한 진찰 및 검사.'),
                                                                         (172, 'oxygen therapy', '산소요법', NULL, '혈중 산소 농도가 낮은 환자에게 산소를 공급하여 저산소증을 개선하는 치료.'),
                                                                         (173, 'pericardiocentesis', '심낭천자', NULL, '심낭(심장을 싸는 막) 내에 비정상적으로 축적된 체액(심낭삼출액)을 바늘로 뽑아내는 시술.'),
                                                                         (174, 'suicide attempt', '자살기도', NULL, '스스로 목숨을 끊으려는 시도.'),
                                                                         (175, 'placenta previa', '전치태반', NULL, '태반이 자궁 입구(자궁경부 내구)를 전체 또는 부분적으로 덮고 있는 상태. 임신 중 출혈 위험.'),
                                                                         (176, 'pulmonary edema', '폐부종', NULL, '폐 조직 내에 비정상적으로 체액이 축적되어 가스 교환 장애를 유발하는 상태.'),
                                                                         (177, 'pulmonary embolism', '폐색전', NULL, '혈전이나 다른 이물질이 폐동맥을 막아 발생하는 치명적일 수 있는 응급 질환.'),
                                                                         (178, 'renal failure', '신장부전', NULL, '신장 기능이 저하되어 노폐물 배설, 체액 및 전해질 균형 유지 등 정상적 역할을 수행하지 못하는 상태.'),
                                                                         (179, 'respiratory acidosis', '호흡성 산증', NULL, '폐의 환기 기능 저하로 이산화탄소가 체내에 축적되어 혈액이 산성화되는 상태.'),
                                                                         (180, 'retinal detachment', '망막박리', NULL, '안구 내벽에 붙어 있는 망막층이 분리되어 떨어지는 질환. 시력 손실 유발.'),
                                                                         (181, 'semicoma', '반혼수', NULL, '강한 자극에만 반응하는 깊은 의식 저하 상태. 혼수(Coma)보다는 얕은 단계. (위의 반혼수와 중복)'),
                                                                         (182, 'shock', '쇼크', NULL, '조직으로의 혈액 순환 및 산소 공급이 급격히 감소하여 세포 기능 장애를 유발하는 생명을 위협하는 상태.'),
                                                                         (183, 'spinal cord trauma', '척수외상', NULL, '외부 충격 등으로 인해 척수에 손상을 입은 상태. 마비 등 신경학적 후유증 유발.'),
                                                                         (184, 'spontaneous abortion', '자연유산', NULL, '의학적 시술 없이 임신 20주 이전에 태아가 자궁 밖으로 배출되거나 사망하는 현상.'),
                                                                         (185, 'sprains and strains', '염자와 좌상', NULL, '염좌는 인대 손상, 좌상은 근육이나 건(힘줄)의 손상을 의미.'),
                                                                         (186, 'stab wounds', '자창', NULL, '칼, 못 등 뾰족한 물체에 찔려서 생긴 상처.'),
                                                                         (187, 'stroke', '뇌졸중', NULL, '뇌혈관의 막힘(뇌경색) 또는 터짐(뇌출혈)으로 인해 뇌 기능이 손상되는 질환. (일반적 뇌졸중, 위의 것들과 일부 중복)'),
                                                                         (188, 'stupor', '혼미', NULL, '강한 자극에만 반응하며 자발적 움직임이 거의 없는 심각한 의식 저하 상태. (위의 혼미와 중복)'),
                                                                         (189, 'syncope', '실신', NULL, '뇌로 가는 혈류가 일시적으로 감소하여 갑자기 의식을 잃고 쓰러지는 현상. \'기절\'.'),
                                                                         (190, 'testicular torsion', '고환꼬임', NULL, '고환이 정삭을 중심으로 꼬여 혈액 공급이 차단되는 응급 비뇨기과 질환.'),
                                                                         (191, 'tetanus', '파상풍', NULL, '파상풍균(Clostridium tetani) 독소에 의해 근육 경직, 경련 등을 유발하는 감염성 질환.'),
                                                                         (192, 'tension pneumothorax', '긴장성 기흉', NULL, '흉강 내 공기가 계속 유입되지만 배출되지 않아 폐와 심장을 압박하는 응급 상태.'),
                                                                         (193, 'thoracentesis', '흉강천자', NULL, '진단 또는 치료 목적으로 흉강(가슴 안 공간)에 바늘을 삽입하여 체액이나 공기를 뽑아내는 시술.'),
                                                                         (194, 'thyroid storm', '갑상샘 중독 발작', NULL, '갑상선 기능 항진증이 극심하게 악화되어 생명을 위협하는 응급 상태.'),
                                                                         (195, 'tracheostomy', '기관절개술', NULL, '기도 확보를 위해 목 앞부분을 절개하여 기관에 직접 관을 삽입하는 수술.'),
                                                                         (196, 'transfusion', '수혈', NULL, '출혈, 빈혈 등으로 부족해진 혈액 성분(적혈구, 혈소판 등)을 정맥을 통해 공급하는 치료.'),
                                                                         (197, 'traumatic aortic dissection', '외상성 대동맥 박리', NULL, '심한 외상으로 인해 대동맥 내벽이 찢어져 혈액이 벽층 사이로 흐르는 응급 상태.'),
                                                                         (198, 'tremor', '떨림', NULL, '신체의 일부 또는 전체가 불수의적으로 규칙적 또는 불규칙적으로 떨리는 증상.'),
                                                                         (199, 'triage', '부상자분류', NULL, '재난 상황 등에서 다수 사상자 발생 시 환자의 중증도와 응급도에 따라 치료 우선순위를 결정하는 과정.'),
                                                                         (200, 'urolithiasis', '요로결석', NULL, '신장, 요관, 방광, 요도 등 소변이 지나가는 길(요로)에 결석이 생기는 질환.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (201, 'upper respiratory infection', '상기도감염', 'URI', '코, 인두, 후두, 부비동 등 상부 호흡기관에 발생하는 감염. (예: 감기, 인후염)'),
                                                                         (202, 'urinary tract infection', '요로감염', 'UTI', '신장, 요관, 방광, 요도 등 비뇨기계에 발생하는 감염.'),
                                                                         (203, 'upper gastrointestinal bleeding', '상부위장관출혈', 'UGI', '식도, 위, 십이지장에서 발생하는 출혈. 토혈이나 흑색변 증상 유발.'),
                                                                         (204, 'Arterial blood gas analysis', '동맥혈가스분석', 'ABGA', '동맥혈을 채취하여 혈액 내 산소, 이산화탄소 농도 및 산성도(pH) 등을 분석하는 검사입니다.'),
                                                                         (205, 'Advanced cardiac life support', '전문심장소생술', 'ACLS', '의료 전문가가 시행하는 심폐소생술 및 약물/장비 사용을 포함한 고급 응급 처치.'),
                                                                         (206, 'automated external defibrillator', '자동제세동기', 'AED', '심정지 환자에게 자동으로 심장 리듬을 분석하고 필요한 경우 전기 충격(제세동)을 가하는 휴대용 의료 기기.'),
                                                                         (207, 'Acute glomerulonephritis', '급성사구체신염', 'AGN', '신장의 사구체(혈액 여과 단위)에 갑자기 발생하는 염증성 질환.'),
                                                                         (208, 'Acute myocardial infarction', '급성심근경색증', 'AMI', '관상동맥이 막혀 심장 근육으로 혈액 공급이 차단되어 심근 세포가 괴사하는 질환. \'심장마비\'.'),
                                                                         (209, 'Acute myeloid leukemia', '급성골수성백혈병', 'AML', '골수의 조혈모세포에서 발생하는 악성 혈액암의 한 종류로, 미성숙 백혈구가 급격히 증식.'),
                                                                         (210, 'Activated partial thromboplastin time', '활성화부분트롬보플라스틴 시간', 'aPTT', '혈액 응고 능력(내인성 경로)을 평가하는 혈액 검사 항목.'),
                                                                         (211, 'Acute respiratory distress syndrome', '급성호흡곤란증후군', 'ARDS', '폐의 심한 염증 및 폐포 손상으로 급격한 호흡곤란을 유발하는 중증 폐 상태.'),
                                                                         (212, 'Acute renal failure', '급성신부전', 'ARF', '신장 기능이 수 시간에서 수일 내에 급격히 저하되는 상태를 말합니다. (AKI와 유사하게 사용되기도 합니다)'),
                                                                         (213, 'Aspartate aminotransferase', '아스파르트산아미노기전달효소', 'AST', '간세포 손상 시 혈중 수치가 증가하는 효소. 간 기능 평가 혈액 검사 항목.'),
                                                                         (214, 'arteriovenous fistula', '동정맥루', 'AVF', '혈액 투석 등을 위해 동맥과 정맥을 수술적으로 연결하여 만든 혈관 통로.'),
                                                                         (215, 'Basilar artery', '뇌저동맥', 'BA', '뇌의 바닥 부분(뇌간, 소뇌 등)에 혈액을 공급하는 주요 동맥.'),
                                                                         (216, 'Basic life support', '기본소생술', 'BLS', '일반인이 시행할 수 있는 심폐소생술(가슴 압박, 인공 호흡) 및 자동제세동기 사용법.'),
                                                                         (217, 'Bone marrow transplantation', '골수이식', 'BMT', '백혈병, 재생불량성빈혈 등 혈액 질환 치료를 위해 건강한 골수 또는 조혈모세포를 이식하는 시술.'),
                                                                         (218, 'Benign prostatic hyperplasia', '전립성비대증', 'BPH', '남성 노인에서 전립선이 비대해져 요도를 압박, 배뇨 증상을 유발하는 질환. (위의 전립선비대증과 중복)'),
                                                                         (219, 'Coronary artery bypass graft', '관상동맥우회술', 'CABG', '막히거나 좁아진 관상동맥을 대체 혈관으로 우회시켜 심장 근육에 혈류를 공급하는 수술.'),
                                                                         (220, 'Continuous ambulatory peritoneal dialysis', '지속외래복막투석', 'CAPD', '환자 스스로 복강 내에 투석액을 주입하고 배액하여 노폐물을 제거하는 복막 투석 방법.'),
                                                                         (221, 'Common bile duct', '총담관', 'CBD', '간에서 만들어진 담즙이 십이지장으로 흘러가는 주된 통로.'),
                                                                         (222, 'Continuous bladder irrigation', '지속적 방광세척', 'CBI', '혈뇨, 감염 등 치료를 위해 방광 내에 지속적으로 생리식염수 등을 주입하고 배출시키는 시술.'),
                                                                         (223, 'Coronary care unit', '관상동맥집중치료실', 'CCU', '급성 심근경색 등 심각한 심장 질환 환자를 집중적으로 치료하고 감시하는 특수 병동.'),
                                                                         (224, 'Congestive heart failure', '울혈심부전', 'CHF', '심장 기능 저하로 혈액 순환이 원활하지 못해 폐나 전신에 체액이 정체(울혈)되는 상태. (위의 울혈성 심부전과 중복)'),
                                                                         (225, 'Cardiopulmonary resuscitation', '심폐소생술', 'CPR', '심정지 환자의 심장 기능과 호흡을 되살리기 위한 응급 처치 (가슴 압박, 인공 호흡).'),
                                                                         (226, 'Chronic renal failure', '만성신부전', 'CRF', '신장 기능이 수개월에서 수년에 걸쳐 점진적, 비가역적으로 저하되는 상태. (위의 만성신부전과 중복)'),
                                                                         (227, 'Cerebrospinal fluid', '뇌척수액', 'CSF', '뇌와 척수를 둘러싸고 보호하며 영양을 공급하는 맑은 체액.'),
                                                                         (228, 'Central venous pressure', '중심정맥압', 'CVP', '상대정맥 또는 우심방 근처의 압력. 체내 수분 상태 및 심장 기능 평가 지표.'),
                                                                         (229, 'Diabetes insipidus', '요붕증', 'DI', '항이뇨호르몬 결핍 또는 작용 이상으로 소변량이 비정상적으로 많아지는 질환.'),
                                                                         (230, 'Disseminated intravascular coagulation', '파종성혈관내응고', 'DIC', '전신 혈관 내에서 미세 혈전이 광범위하게 형성되어 출혈과 장기 부전을 유발하는 심각한 상태.'),
                                                                         (231, 'Diabetic ketoacidosis', '당뇨병케톤산증', 'DKA', '인슐린 부족으로 혈당이 급격히 상승하고 케톤체가 축적되어 발생하는 당뇨병의 심각한 급성 합병증.'),
                                                                         (232, 'do not resuscitate', '소생술포기', 'DNR', '심정지 시 심폐소생술을 시행하지 말 것을 미리 밝히는 환자의 의사 결정.'),
                                                                         (233, 'Dead on arrival', '도착시사망', 'DOA', '병원 도착 시 이미 사망한 상태.'),
                                                                         (234, 'Deep vein thrombosis', '심부정맥 혈전증', 'DVT', '주로 다리 깊은 곳의 정맥에 혈전(피떡)이 생기는 질환. (위의 심부정맥혈전증과 중복)'),
                                                                         (235, 'Diagnosis', '진단', 'Dx', '환자의 증상, 병력, 검사 결과 등을 종합하여 질병의 종류나 상태를 판단하는 과정.'),
                                                                         (236, 'electrocardiogram', '심전도', 'ECG', '심장의 전기적 활동을 그래프로 기록하여 심장 상태를 평가하는 검사.'),
                                                                         (237, 'end stage renal disease', '말기 신장질환', 'ESRD', '신장 기능이 영구적으로 거의 소실되어 투석이나 신장 이식이 필요한 상태.'),
                                                                         (238, 'extracorporeal shock wave lithotripsy', '체외충격파쇄석술', 'ESWL', '몸 밖에서 발생시킨 충격파를 이용하여 신장이나 요로 결석을 잘게 부수는 비수술적 치료.'),
                                                                         (239, 'endoscopic ultrasonography', '내시경초음파검사', 'EUS', '내시경 끝에 초음파 장치를 부착하여 소화기관 및 주변 장기를 정밀 관찰하는 검사.'),
                                                                         (240, 'endoscopic variceal ligation', '내시경적 정맥류 결찰술', 'EVL', '내시경을 통해 식도나 위의 정맥류를 고무 밴드로 묶어 출혈을 예방하거나 치료하는 시술.'),
                                                                         (241, 'foreign-body airway obstruction', '기도이물폐쇄증', 'FBAO', '음식물이나 작은 물체 등이 기도를 막아 호흡 곤란을 일으키는 상태.'),
                                                                         (242, 'fine needle aspiration', '가는바늘흡인', 'FNA', '종양이나 병변 부위에 가는 바늘을 찔러 세포나 조직을 채취하여 검사하는 방법.'),
                                                                         (243, 'fever unknown origin', '원인불명 열', 'FUO', '3주 이상 지속되는 38.3℃ 이상의 발열이 충분한 검사에도 불구하고 원인이 밝혀지지 않는 경우.'),
                                                                         (244, 'fracture', '골절', 'FX', '뼈의 연속성이 완전하거나 불완전하게 끊어진 상태.'),
                                                                         (245, 'glasgow coma scale', '글래스고우혼수척도', 'GCS', '환자의 의식 수준을 눈 뜨기, 언어 반응, 운동 반응 세 가지 항목으로 평가하는 표준화된 점수 체계. (위와 중복)'),
                                                                         (246, 'gastroesophageal reflux disease', '위식도역류질환', 'GERD', '위산이나 위 내용물이 식도로 역류하여 가슴쓰림 등의 증상을 유발하는 질환. (위와 중복)'),
                                                                         (247, 'gastrofiberscope', '위내시경', 'GFS', '입을 통해 내시경을 삽입하여 식도, 위, 십이지장 상부를 관찰하는 검사.'),
                                                                         (248, 'hepatocellular carcinoma', '간암', 'HCC', '간세포에서 발생하는 악성 종양.'),
                                                                         (249, 'hemodialysis', '혈액투석', 'HD', '기계를 이용하여 혈액 내 노폐물과 과다 수분을 제거하고 전해질 균형을 맞추는 신대체 요법.'),
                                                                         (250, 'hepatic encephalopathy', '간성뇌증 ( 간성혼수 )', 'HEP', '심한 간 기능 저하로 독성 물질이 뇌에 영향을 미쳐 의식 변화, 행동 이상 등을 유발하는 상태.'),
                                                                         (251, 'human immunodeficiency virus', '사람면역결핍바이러스', 'HIV', '후천성면역결핍증(AIDS)을 유발하는 바이러스. 면역 세포를 파괴하여 면역력을 저하시킴.'),
                                                                         (252, 'human leukocyte antigen', '사람백혈구항원', 'HLA', '백혈구 표면에 존재하는 항원으로, 장기 이식 시 조직 적합성을 결정하는 주요 인자.'),
                                                                         (253, 'hereditary spherocytosis', '유전구형적혈구증', 'HS', '적혈구 막 단백질 이상으로 적혈구가 공 모양으로 변형되어 쉽게 파괴되는 유전성 용혈성 빈혈.'),
                                                                         (254, 'incision & drainage', '절개와 배농', 'I & D', '농양(고름집) 부위를 절개하여 고름을 빼내는 시술.'),
                                                                         (255, 'insulin dependent diabetes mellitus', '인슐린의존성당뇨병', 'IDDM', '췌장에서 인슐린 분비가 거의 또는 전혀 되지 않아 생존을 위해 인슐린 주사가 필수적인 당뇨병 (주로 제1형 당뇨병).'),
                                                                         (256, 'intrahepatic bile duct', '간내담관', 'IHBD', '간 조직 내부에 위치하며 담즙을 운반하는 작은 관들.'),
                                                                         (257, 'impression', '예진', 'IMP', '환자 진찰 후 의사가 내리는 잠정적인 진단 또는 상태 평가.'),
                                                                         (258, 'intraosseous access', '골내접근', 'IO', '응급 상황에서 정맥 확보가 어려울 때 뼈의 골수강 내로 바늘을 삽입하여 약물이나 수액을 주입하는 방법.'),
                                                                         (259, 'intravenous pyelography', '정맥신우조영술', 'IVP', '조영제를 정맥 주사한 후 X선 촬영을 통해 신장, 요관, 방광의 형태와 기능을 평가하는 검사.'),
                                                                         (260, 'kidney, ureter, bladder', '신장 , 요관 , 방광', 'KUB', '복부 X선 촬영 시 신장, 요관, 방광 부위를 주로 관찰하여 요로 결석 등을 진단하는 영상 검사.'),
                                                                         (261, 'left anterior descending branch', '좌전하행지', 'LAD', '좌측 관상동맥의 주요 분지 중 하나로, 심장의 앞쪽과 좌심실에 혈액을 공급하는 중요한 혈관.'),
                                                                         (262, 'liver function test', '간기능검사', 'LFT', '간의 건강 상태와 기능 이상 여부를 평가하기 위해 혈액 내 효소, 단백질, 빌리루빈 수치 등을 측정하는 검사.'),
                                                                         (263, 'left lower quadrant', '좌하복부', 'LLQ', '배를 네 부분으로 나누었을 때 왼쪽 아래 영역.'),
                                                                         (264, 'loss of consciousness', '의식상실', 'LOC', '외부 자극에 반응하지 못하고 주변 환경을 인지하지 못하는 상태.'),
                                                                         (265, 'lumbar puncture', '요추천자', 'LP', '진단 또는 치료 목적으로 허리 부위 척추 사이에 바늘을 삽입하여 뇌척수액을 채취하거나 약물을 주입하는 시술.'),
                                                                         (266, 'left upper quadrant', '좌상복부', 'LUQ', '배를 네 부분으로 나누었을 때 왼쪽 윗 영역.'),
                                                                         (267, 'left ventricular hypertrophy', '좌심실비대', 'LVH', '심장의 좌심실 벽이 비정상적으로 두꺼워진 상태. 고혈압 등이 원인일 수 있음.'),
                                                                         (268, 'military antishock trousers', '쇼크바지', 'MAST', '쇼크 환자의 하지 혈류를 상체로 집중시키고 출혈을 조절하기 위해 사용하는 공기 주입식 특수 바지.'),
                                                                         (269, 'myelodysplastic syndrome', '골수이형성증후군', 'MDS', '골수 기능 이상으로 건강한 혈액 세포를 충분히 만들지 못하는 질환군. 백혈병으로 진행 가능.'),
                                                                         (270, 'myocardial infarction', '심근경색증', 'MI', '관상동맥 혈류 차단으로 심장 근육이 괴사하는 질환. (급성심근경색증과 유사)'),
                                                                         (271, 'magnetic resonance imaging', '자기공명영상법', 'MRI', '강력한 자기장과 고주파를 이용하여 인체 단면 영상을 얻는 정밀 검사.'),
                                                                         (272, 'mitral valve replacement', '승모판대치술', 'MVR', '손상되거나 기능이 저하된 승모판을 인공 판막으로 교체하는 심장 수술.'),
                                                                         (273, 'nausea', '오심', NULL, '오심은 메스꺼움을 느끼는 불쾌한 감각'),
                                                                         (274, 'pediatric advanced life support', '소아전문소생술', 'PALS', '영아 및 소아 심정지 환자에게 시행하는 전문화된 응급 처치 및 소생술.'),
                                                                         (275, 'pulseless electrical activity', '무맥성전기활동', 'PEA', '심전도 상에서는 전기적 활동이 관찰되나 실제로는 맥박이 촉진되지 않는 심정지 상태.'),
                                                                         (276, 'pulmonary fuction test', '폐기능검사', 'PFT', '폐활량, 호흡 속도 등을 측정하여 폐의 전반적인 기능을 평가하는 검사.'),
                                                                         (277, 'pulmonary hypertension', '폐고혈압', 'PH', '폐동맥의 혈압이 비정상적으로 높아져 우심실에 부담을 주는 상태.'),
                                                                         (278, 'percutaneous transhepatic biliary drainage', '경피경간 담도 배액술', 'PTBD', '피부와 간을 통해 담관에 배액관을 삽입하여 막힌 담즙을 몸 밖으로 빼내는 시술.'),
                                                                         (279, 'premature ventricular contraction', '심실조기수축', 'PVC', '심실에서 정상적인 동방결절 신호보다 먼저 비정상적인 전기 자극이 발생하여 심실이 예정보다 일찍 수축하는 부정맥.'),
                                                                         (280, 'subdural hematoma', '경막하혈종', 'SDH', '뇌 경막 아래 공간(경막하 공간)에 혈액이 고인 상태. 외상 등으로 발생.'),
                                                                         (281, 'Absolute Bed Rest', '절대 침상 안정', 'ABR', '질병의 치료나 회복을 위해 환자가 침대에서 벗어나지 않고 절대적으로 안정을 취하도록 하는 지시입니다.'),
                                                                         (282, 'Acute Kidney Injury', '급성 신장손상', 'AKI', '신장 기능이 급격하게 저하되어 체내 노폐물 제거 및 체액 균형 유지에 문제가 생기는 상태입니다.'),
                                                                         (283, 'Acute Renal Failure', '급성 신부전', 'ARF', '신장 기능이 수 시간에서 수일 내에 급격히 저하되는 상태를 말합니다. (AKI와 유사하게 사용되기도 합니다)'),
                                                                         (284, 'Acute Respiratory Distress Syndrome', '급성호흡곤란증후군', 'ARDS', '폐의 심한 염증 및 폐포 손상으로 급격한 호흡곤란을 유발하는 중증 폐 상태.'),
                                                                         (285, 'Acute Respiratory Failure', '급성 호흡부전', 'ARF', '폐의 가스 교환 기능이 급격히 저하되어 혈액 내 산소 농도가 낮아지고 이산화탄소 농도가 높아지는 상태입니다.'),
                                                                         (286, 'Advanced Gastric Cancer', '진행성 위암', 'AGC', '암세포가 위 점막하층을 넘어 근육층 이상으로 침범했거나 주변 림프절 또는 다른 장기로 전이된 위암입니다.'),
                                                                         (287, 'Aneurysm', '동맥류', NULL, '동맥 혈관 벽이 약해져서 비정상적으로 부풀어 오르는 상태입니다.'),
                                                                         (288, 'Anterior Cerebral Artery', '전대뇌동맥', 'ACA', '뇌의 앞부분과 안쪽 면에 혈액을 공급하는 주요 동맥 중 하나입니다.'),
                                                                         (289, 'Anterior Communicating Artery Aneurysm', '전교통동맥류', 'AComA', '뇌의 좌우 전대뇌동맥을 연결하는 전교통동맥에 발생하는 동맥류(혈관이 꽈리처럼 부풀어 오르는 것)입니다.'),
                                                                         (290, 'Aphasia', '실어증', NULL, '뇌 손상으로 인해 언어 이해나 표현 능력(말하기, 듣기, 읽기, 쓰기)이 저하 또는 상실된 상태.'),
                                                                         (291, 'Apnea', '무호흡', NULL, '일시적으로 호흡이 정지된 상태를 말합니다.'),
                                                                         (292, 'Arterial Blood Gas Analysis', '동맥혈 가스분석', 'ABGA', '동맥혈을 채취하여 혈액 내 산소, 이산화탄소 농도 및 산성도(pH) 등을 분석하는 검사입니다.'),
                                                                         (293, 'Arterial Line', '동맥선 (동맥 카테터)', 'A-Line', '지속적인 혈압 감시 및 동맥혈 채취를 위해 동맥 내에 삽입하는 카테터입니다.'),
                                                                         (294, 'Arteriovenous Malformation', '동정맥 기형', 'AVM', '동맥과 정맥이 모세혈관 없이 비정상적으로 직접 연결된 혈관 기형입니다.'),
                                                                         (295, 'Aspartate Aminotransferase', '간기능 효소 혈청검사 (아스파르테이트 아미노전이효소)', 'AST', '간세포 손상 시 혈중으로 유출되는 효소로, 간 기능 이상 여부를 판단하는 혈액검사 항목 중 하나입니다.'),
                                                                         (296, 'Atelectasis', '무기폐', NULL, '폐의 일부 또는 전체가 허탈되어 공기가 들어가지 못하는 상태입니다.'),
                                                                         (297, 'Atrial Premature Contraction', '심방조기수축', 'APC', '심장의 정상적인 박동 외에 심방에서 비정상적인 전기 신호가 먼저 발생하여 심장이 예정보다 일찍 수축하는 부정맥의 일종입니다.'),
                                                                         (298, 'Blood Sugar Test', '혈당 검사', 'BST', '혈액 내 포도당 농도를 측정하는 검사로, 당뇨병 진단 및 관리에 중요합니다.'),
                                                                         (299, 'Cardiopulmonary Resuscitation', '심폐소생술', 'CPR', '심장 박동과 호흡이 멈춘 환자에게 인공적으로 혈액을 순환시키고 호흡을 돕는 응급 처치입니다.'),
                                                                         (300, 'Central Venous Pressure', '중심정맥압', 'CVP', '상대정맥 또는 우심방 근처의 압력으로, 체내 혈액량 및 우심실 기능 상태를 간접적으로 평가하는 지표입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (301, 'Cerebral Blood Flow', '뇌혈류량', 'CBF', '단위 시간당 뇌 조직을 통과하는 혈액의 양을 의미합니다.'),
                                                                         (302, 'Cerebral Infarction', '뇌경색', NULL, '뇌혈관이 막혀 뇌 조직으로 혈액 공급이 중단되면서 뇌세포가 괴사하는 질환입니다.'),
                                                                         (303, 'Cerebrospinal Fluid', '뇌척수액', 'CSF', '뇌와 척수를 둘러싸고 보호하며 영양을 공급하는 맑은 액체입니다.'),
                                                                         (304, 'Cerebrovascular Accident', '뇌졸중', 'CVA', '뇌혈관의 문제(막힘 또는 터짐)로 인해 뇌 기능이 손상되는 질환으로, 뇌경색과 뇌출혈을 포함합니다.'),
                                                                         (305, 'Cerebrovascular Disease', '뇌혈관 질환', 'CVD', '뇌에 혈액을 공급하는 혈관에 발생하는 모든 질환을 통칭합니다.'),
                                                                         (306, 'Chronic Obstructive Pulmonary Disease', '만성폐쇄성폐질환', 'COPD', '유해한 입자나 가스 흡입으로 인해 폐에 만성적인 염증이 발생하여 기도와 폐 실질이 손상되고 공기 흐름이 제한되는 질환입니다.'),
                                                                         (307, 'Chronic Renal Failure', '만성 신부전', 'CRF', '수개월에서 수년에 걸쳐 신장 기능이 점진적으로 저하되는 상태입니다. (CKD, 만성 신장병과 유사)'),
                                                                         (308, 'Complete Blood Cell Count', '전혈구 검사', 'CBC', '혈액 내 적혈구, 백혈구, 혈소판의 수와 형태 등을 분석하는 기본적인 혈액 검사입니다.'),
                                                                         (309, 'Compound Fracture (Open Fracture)', '복합골절 (개방골절)', NULL, '골절된 뼈의 일부가 피부를 뚫고 외부로 노출된 상태의 골절입니다.'),
                                                                         (310, 'Computed Tomography', '컴퓨터 단층촬영', 'CT', 'X선을 이용하여 신체의 단면 영상을 얻는 영상 진단 방법입니다.'),
                                                                         (311, 'Craniectomy', '두개골 절제술', NULL, '두개골의 일부를 제거하는 수술로, 심한 뇌부종 시 뇌압을 낮추기 위해 시행될 수 있습니다. 제거된 뼈는 나중에 다시 이식하거나 인공뼈로 대체할 수 있습니다.'),
                                                                         (312, 'Cranioplasty', '두개골 성형술', NULL, '두개골 결손 부위를 자가골 또는 인공 물질을 이용하여 복원하는 수술입니다.'),
                                                                         (313, 'Craniotomy', '개두술', NULL, '두개골의 일부를 절개하여 뇌를 노출시키는 수술 방법입니다. 뇌종양 제거, 혈종 배액 등에 사용됩니다.'),
                                                                         (314, 'Deep Tendon Reflex', '심부건 반사', 'DTR', '힘줄을 가볍게 두드렸을 때 해당 근육이 불수의적으로 수축하는 반사입니다. 신경계 이상을 평가하는 데 사용됩니다.'),
                                                                         (315, 'Deep Vein Thrombosis', '심부정맥 혈전증', 'DVT', '주로 다리의 깊은 부위 정맥에 혈전(피떡)이 생기는 질환입니다.'),
                                                                         (316, 'Delirium Tremens', '섬망', 'DT (Delirium Tremens) / Delirium', 'Delirium Tremens (진전섬망): 주로 알코올 금단 시 나타나는 심한 섬망 상태. / Delirium (섬망): 의식, 주의력, 인지 기능에 급격한 변화가 나타나는 상태입니다.(Delirium)'),
                                                                         (317, 'Diffusing Capacity of the Lung for Carbon Monoxide', '일산화탄소 폐확산능 검사', 'DLCO', '폐가 혈액으로 산소를 얼마나 잘 전달하는지(가스 교환 능력)를 평가하는 폐기능 검사입니다.'),
                                                                         (318, 'Do Not Resuscitate', '심폐소생술 불필요 (연명의료 중단 결정)', 'DNR', '환자나 보호자의 결정에 따라 심정지 시 심폐소생술을 시행하지 않도록 하는 의학적 지시입니다.'),
                                                                         (319, 'Early Gastric Cancer', '조기 위암', 'EGC', '암세포가 위 점막층 또는 점막하층에 국한되어 있는 초기 단계의 위암입니다.'),
                                                                         (320, 'Electrocardiogram', '심전도 검사', 'EKG (ECG)', '심장의 전기적 활동을 그래프로 기록하여 심장 질환을 진단하는 검사입니다.'),
                                                                         (321, 'Electroencephalography', '뇌파검사', 'EEG', '두피에 전극을 부착하여 뇌의 전기적 활동을 기록하고 분석하는 검사로, 간질, 수면장애 등 진단에 사용됩니다.'),
                                                                         (322, 'Electromyogram', '근전도 검사', 'EMG', '근육의 전기적 활동을 기록하여 신경 및 근육 질환을 진단하는 검사입니다.(Electromyography)'),
                                                                         (323, 'Encephalopathy', '뇌병증', NULL, '뇌 기능 장애를 통칭하는 용어로, 다양한 원인에 의해 발생할 수 있습니다.'),
                                                                         (324, 'Epidural Hematoma', '경막외 혈종', 'EDH', '두개골과 뇌를 감싸는 가장 바깥쪽 막(경막) 사이에 혈액이 고이는 질환입니다. 주로 두부 외상으로 인해 발생합니다.'),
                                                                         (325, 'External Ventricular Drainage', '체외 뇌실 배액술', 'EVD', '뇌실 내에 도관을 삽입하여 뇌척수액을 체외로 배출시켜 뇌압을 조절하고 뇌척수액을 검사하는 시술입니다.'),
                                                                         (326, 'Fraction of Inspired Oxygen', '흡입 산소 농도', 'FiO₂', '환자가 들이마시는 공기 중 산소의 비율 또는 농도를 의미합니다.'),
                                                                         (327, 'Fresh Frozen Plasma', '신선 동결 혈장', 'FFP', '전혈에서 혈구를 제외한 혈장 성분을 채취하여 신선한 상태로 동결시킨 혈액 제제입니다. 응고 인자 보충 등에 사용됩니다.'),
                                                                         (328, 'Glomerular Filtration Rate', '사구체 여과율', 'GFR', '신장이 일정 시간 동안 혈액에서 특정 물질을 걸러내는 능력을 나타내는 지표로, 신장 기능을 평가하는 데 사용됩니다.'),
                                                                         (329, 'Hemiplegia', '편마비', NULL, '신체의 왼쪽 또는 오른쪽 절반이 마비된 상태를 말합니다.'),
                                                                         (330, 'Hemodialysis', '혈액투석', 'HD', '신부전 환자의 혈액을 투석기를 이용해 체외로 빼내어 노폐물과 과다한 수분을 제거한 후 다시 체내로 주입하는 치료 방법입니다.'),
                                                                         (331, 'Hemothorax', '혈흉', NULL, '흉막강 내에 혈액이 고이는 상태로, 주로 외상이나 수술 후 발생할 수 있습니다.'),
                                                                         (332, 'Hepatocellular Carcinoma', '간(세포)암', 'HCC', '간세포에서 기원하는 악성 종양으로, 가장 흔한 원발성 간암입니다.'),
                                                                         (333, 'Hyperkalemia', '고칼륨혈증', NULL, '혈액 내 칼륨 농도가 정상 수치보다 높은 상태로, 심장 기능 이상 등을 초래할 수 있습니다.'),
                                                                         (334, 'Impression', '추정 진단 (임상적 추정)', 'Imp.', '환자의 증상, 병력, 검사 결과 등을 종합하여 의사가 내리는 잠정적인 진단을 의미합니다.'),
                                                                         (335, 'Increased Intracranial Pressure', '두개강내압 상승', 'IICP', '두개골 내부의 압력이 비정상적으로 높아지는 상태로, 뇌 부종, 혈종, 종양 등에 의해 발생할 수 있습니다.'),
                                                                         (336, 'Intensive Care Unit', '중환자실', 'ICU', '생명 유지를 위해 집중적인 치료와 감시가 필요한 중증 환자를 위한 병실입니다.'),
                                                                         (337, 'Intracerebral Hemorrhage', '뇌내 출혈', 'ICH', '뇌 실질 내에서 혈관이 터져 혈액이 고이는 상태로, 뇌 조직 손상을 유발합니다.'),
                                                                         (338, 'Intracerebral Hematoma', '뇌내 혈종', NULL, '뇌 실질 내에서 혈관이 터져 혈액이 고이는 상태로, 뇌 조직 손상을 유발합니다.'),
                                                                         (339, 'Intraventricular Hemorrhage', '뇌실내 출혈', 'IVH', '뇌 안에 있는 뇌척수액 공간인 뇌실 내로 출혈이 발생하는 것입니다.'),
                                                                         (340, 'Ischemic Heart Disease', '허혈성 심질환', 'IHD', '관상동맥 질환으로 인해 심장 근육으로의 혈액 공급이 부족해져 발생하는 질환들을 통칭합니다. (예: 협심증, 심근경색증)'),
                                                                         (341, 'Left Ventricular Hypertrophy', '좌심실 비대', 'LVH', '심장의 좌심실 벽이 비정상적으로 두꺼워지는 상태로, 고혈압 등이 원인이 될 수 있습니다.'),
                                                                         (342, 'Liver Cirrhosis', '간경화증', 'LC', '간이 지속적인 손상으로 인해 섬유화되어 기능이 저하되는 만성 간질환입니다.'),
                                                                         (343, 'Loss of Consciousness', '의식 소실', 'LOC', '외부 자극에 반응하지 못하고 주변 환경을 인지하지 못하는 상태를 말합니다.'),
                                                                         (344, 'Lumbar Puncture', '요추 천자', NULL, '허리 부분의 척추 사이에 바늘을 삽입하여 뇌척수액을 채취하거나 약물을 주입하는 시술입니다.'),
                                                                         (345, 'Magnetic Resonance Imaging', '자기공명영상', 'MRI', '강력한 자기장과 고주파를 이용하여 신체의 단면 영상을 얻는 영상 진단 방법입니다.'),
                                                                         (346, 'Methicillin-Resistant Staphylococcus Aureus', '메티실린 내성 황색포도상구균', 'MRSA', '메티실린을 포함한 여러 항생제에 내성을 보이는 황색포도상구균으로, 병원 내 감염의 주요 원인균 중 하나입니다.'),
                                                                         (347, 'Middle Cerebral Artery', '중대뇌동맥', 'MCA', '뇌의 넓은 영역, 특히 바깥쪽과 위쪽 부분에 혈액을 공급하는 가장 큰 뇌혈관입니다.'),
                                                                         (348, 'Myocardial Infarction', '심근경색증', 'MI', '관상동맥이 막혀 심장 근육으로의 혈액 공급이 차단되어 심장 근육 세포가 괴사하는 질환입니다.'),
                                                                         (349, 'Nonsteroidal Anti-inflammatory Drugs', '비스테로이드성 항염증제', 'NSAIDs', '염증, 통증, 발열을 완화시키는 약물군으로, 스테로이드 구조를 갖지 않습니다. (예: 이부프로펜, 아스피린)'),
                                                                         (350, 'Orthopnea', '기좌호흡', NULL, '누워 있을 때 호흡곤란이 심해지고, 앉거나 서면 완화되는 증상입니다. 심부전 등에서 나타날 수 있습니다.'),
                                                                         (351, 'Paralysis', '마비', NULL, '근육의 기능이 상실되어 움직일 수 없는 상태를 말합니다.'),
                                                                         (352, 'Paraplegia', '하반신 마비', NULL, '양쪽 다리와 몸통의 일부가 마비된 상태를 말합니다.'),
                                                                         (353, 'Partial Pressure of Oxygen in Arterial Blood', '동맥혈 산소분압', 'PaO₂', '동맥혈에 녹아있는 산소의 부분 압력으로, 폐의 가스 교환 능력을 평가하는 지표입니다.'),
                                                                         (354, 'Patient-Controlled Analgesia', '자가 통증 조절 장치', 'PCA', '환자 스스로 필요할 때마다 버튼을 눌러 설정된 양의 진통제를 투여받을 수 있도록 하는 장치입니다.'),
                                                                         (355, 'Percutaneous Transhepatic Biliary Drainage', '경피적 경간담도배액술', 'PTBD', '피부를 통해 간을 거쳐 담도에 배액관을 삽입하여 막힌 담즙을 배출시키는 시술입니다.'),
                                                                         (356, 'Pleural Effusion', '늑막삼출(흉수)', NULL, '폐를 둘러싸고 있는 두 겹의 흉막 사이에 비정상적으로 액체가 축적되는 상태입니다.'),
                                                                         (357, 'Pleuritis', '흉막염 (늑막염)', NULL, '폐를 둘러싸고 있는 흉막에 염증이 생긴 상태로, 흔히 가슴 통증을 유발합니다.(Pleurisy)'),
                                                                         (358, 'Pneumothorax', '기흉', NULL, '폐를 둘러싸고 있는 흉막강 내에 공기가 차서 폐가 허탈되는 상태입니다.'),
                                                                         (359, 'Positive End-Expiratory Pressure', '호기말 양압', 'PEEP', '인공호흡기 치료 시 호기가 끝난 후에도 폐에 일정한 양압을 유지시켜 폐포의 허탈을 방지하고 산소화를 개선하는 방법입니다.'),
                                                                         (360, 'Positron Emission Tomography', '양전자방출 단층촬영', 'PET', '방사성 동위원소를 이용하여 신체의 대사 과정을 영상화하는 핵의학 검사 방법입니다. 암 진단 및 병기 설정 등에 사용됩니다.'),
                                                                         (361, 'Premature Ventricular Contraction', '심실조기수축', 'PVC / VPC', '심장의 정상적인 박동 외에 심실에서 비정상적인 전기 신호가 먼저 발생하여 심장이 예정보다 일찍 수축하는 부정맥의 일종입니다.(Ventricular Premature Contraction)'),
                                                                         (362, 'Pro Re Nata (Latin: As needed)', '필요시 (처방)', 'PRN', '약물 등을 \'필요할 때마다\' 투여하라는 의학적 지시입니다.'),
                                                                         (363, 'Pulmonary Edema', '폐부종', NULL, '폐포 내에 비정상적으로 많은 양의 체액이 축적되어 호흡곤란을 유발하는 상태입니다.'),
                                                                         (364, 'Pulmonary Embolism', '폐색전증', 'PE', '혈전(주로 다리 정맥에서 생긴 DVT)이 혈류를 타고 이동하여 폐동맥을 막는 질환입니다.'),
                                                                         (365, 'Pulmonary Tuberculosis', '폐결핵', 'Tbc (TB)', '결핵균(Mycobacterium tuberculosis)이 폐에 감염되어 발생하는 만성 감염성 질환입니다.'),
                                                                         (366, 'Quadriplegia', '사지마비', NULL, '팔과 다리 모두가 마비된 상태를 말합니다.(Tetraplegia)'),
                                                                         (367, 'Right Lower Lobe', '폐 우하엽', 'RLL', '오른쪽 폐의 아래쪽 부분을 가리킵니다. (폐는 여러 엽으로 구성됨)'),
                                                                         (368, 'Rule Out', '감별 진단 (Rule out)', 'R/O (r/o)', '특정 질환이 의심될 때, 이를 확진하거나 배제하기 위해 다른 가능한 진단들을 고려하고 검토하는 과정을 의미합니다. 또는 아직 확정되지 않은 진단을 나타낼 때 사용합니다.'),
                                                                         (369, 'Secretion', '분비물', NULL, '생체 조직이나 세포에서 특정 물질이 생성되어 방출되는 것, 또는 그 물질 자체를 의미합니다.'),
                                                                         (370, 'Shortness of Breath', '호흡곤란', 'SOB', '숨쉬기가 어렵거나 불편한 느낌, 숨이 가쁜 증상을 말합니다.'),
                                                                         (371, 'Subarachnoid Hemorrhage', '지주막하 출혈', 'SAH', '뇌를 둘러싸고 있는 지주막과 연막 사이의 공간(지주막하 공간)으로 혈액이 유출되는 질환입니다. 주로 뇌동맥류 파열로 발생합니다.'),
                                                                         (372, 'Subdural Hematoma', '경막하 혈종', 'SDH', '뇌를 감싸는 경막 아래, 지주막 위에 혈액이 고이는 질환으로, 급성 또는 만성으로 발생할 수 있습니다.(Hemorrhage)'),
                                                                         (373, 'Sublingual', '설하 투여', 'SL', '약물을 혀 밑에 넣어 점막을 통해 흡수시키는 투여 경로입니다.'),
                                                                         (374, 'Synchronized Intermittent Mandatory Ventilation', '동시성 간헐적 강제 환기', 'SIMV', '인공호흡기의 한 종류로, 환자의 자발 호흡을 허용하면서 설정된 횟수만큼 강제 환기를 제공하는 방식입니다.'),
                                                                         (375, 'Syndrome of Inappropriate Antidiuretic Hormone Secretion', '항이뇨호르몬 부적절 분비 증후군', 'SIADH', '항이뇨호르몬(ADH)이 생리적 필요 이상으로 과다하게 분비되어 체내 수분이 배출되지 못하고 저나트륨혈증 등을 유발하는 질환입니다.'),
                                                                         (376, 'Thoracentesis', '흉막천자 (흉강천자)', NULL, '흉막강 내에 고인 액체(흉수)를 진단 또는 치료 목적으로 바늘을 이용해 뽑아내는 시술입니다.'),
                                                                         (377, 'Total Parenteral Nutrition', '총 비경구 영양', 'TPN', '구강이나 위장관을 통해 영양 공급이 불가능하거나 불충분할 때, 정맥을 통해 필수 영양소를 공급하는 방법입니다.'),
                                                                         (378, 'Traffic Accident', '교통사고', 'TA', '도로 교통과 관련된 사고로, 다양한 신체 손상을 유발할 수 있습니다.'),
                                                                         (379, 'Transient Ischemic Attack', '일과성 뇌허혈 발작', 'TIA', '뇌혈관이 일시적으로 막혔다가 다시 뚫리면서 뇌졸중과 유사한 증상이 나타났다가 수 분에서 수 시간 내에 사라지는 상태입니다. \'미니 뇌졸중\'이라고도 불립니다.'),
                                                                         (380, 'Urinary Tract Infection', '요로감염', 'UTI', '신장, 요관, 방광, 요도 등 비뇨기계의 일부에 세균 등이 감염되어 염증이 발생하는 질환입니다.'),
                                                                         (381, 'Vancomycin-Resistant Enterococci', '반코마이신 내성 장알균(장구균)', 'VRE', '항생제인 반코마이신에 내성을 보이는 장알균(장구균)으로, 치료가 어려운 감염을 유발할 수 있습니다.'),
                                                                         (382, 'Vancomycin-Resistant Staphylococcus Aureus', '반코마이신 내성 황색포도상구균', 'VRSA', '항생제인 반코마이신에 내성을 보이는 황색포도상구균으로, 매우 치료가 어려운 감염을 유발합니다.'),
                                                                         (383, 'Vasospasm', '혈관 경련', NULL, '혈관 벽 근육이 비정상적으로 수축하여 혈관이 좁아지는 현상입니다.'),
                                                                         (384, 'Venous Thrombosis', '정맥 혈전증', NULL, '정맥 내에 혈전(피떡)이 형성되어 혈류를 막거나 방해하는 질환입니다. (DVT는 심부정맥 혈전증을 특정)'),
                                                                         (385, 'Ventriculo-peritoneal Shunt', '뇌실-복막강 단락술', 'V-P shunt', '뇌실 내에 과도하게 축적된 뇌척수액을 관을 통해 복강으로 배출시켜 뇌압을 조절하는 수술입니다.'),
                                                                         (386, 'Fracture', '골절', 'Fx', '외부의 힘에 의해 뼈의 연속성이 완전 혹은 불완전하게 소실된 상태, 즉 뼈가 부러진 것을 말합니다.'),
                                                                         (387, 'Vertebroplasty', '척추성형술', NULL, '골다공증 등으로 인해 약해진 척추뼈에 주사로 골 시멘트를 주입하여 뼈를 강화하고 통증을 줄이는 시술입니다.'),
                                                                         (388, 'Osteomalacia', '골연화증', NULL, '뼈에 칼슘과 인이 부족하여 뼈가 약해지고 변형되기 쉬운 성인의 대사성 뼈 질환입니다.'),
                                                                         (389, 'Amputation', '절단', NULL, '질병이나 외상으로 인해 신체의 일부(주로 팔, 다리)를 외과적으로 제거하는 것입니다.'),
                                                                         (390, 'Fat Embolism', '지방색전증', NULL, '골절 등으로 인해 골수 내 지방이 혈관으로 들어가 혈관을 막는 심각한 합병증입니다.'),
                                                                         (391, 'Valgus', '외반', NULL, '신체의 일부가 몸의 중심선으로부터 바깥쪽으로 휘어진 변형을 말합니다. (예: 무지외반증)'),
                                                                         (392, 'Ganglion', '결절종', NULL, '관절이나 힘줄 주변에 생기는 젤리 같은 물질이 찬 물혹입니다.'),
                                                                         (393, 'Physical Therapy', '물리치료', 'PT', '열, 전기, 운동 등을 이용하여 통증을 완화하고 신체 기능을 회복, 증진시키는 치료입니다.'),
                                                                         (394, 'Sprain', '염좌', NULL, '관절을 지지하는 인대가 외부 충격 등으로 인해 늘어나거나 일부 찢어지는 손상입니다.'),
                                                                         (395, 'Intervertebral Disk', '추간판, 디스크', 'IVD', '척추뼈 사이에 위치하여 충격을 흡수하는 연골 조직입니다.'),
                                                                         (396, 'Gout', '통풍', NULL, '혈액 내 요산 농도가 높아지면서 요산 결정이 관절에 침착하여 극심한 통증과 염증을 유발하는 질환입니다.'),
                                                                         (397, 'Multiple Myeloma', '다발성 골수종', 'MM', '골수에서 항체를 만드는 형질세포가 비정상적으로 증식하는 혈액암의 일종입니다.'),
                                                                         (398, 'Traction', '견인', NULL, '골절이나 탈구된 뼈를 바로 맞추거나 통증 완화를 위해 신체의 일부를 지속적으로 당기는 치료법입니다.'),
                                                                         (399, 'Scoliosis', '척추측만증', NULL, '척추가 정면에서 보았을 때 옆으로 C자나 S자 형태로 휘어지는 변형입니다.'),
                                                                         (400, 'Bone Graft', '골이식', NULL, '뼈의 결손 부위를 다른 뼈(자가 또는 타인)나 인공 물질로 채워주는 수술입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (401, 'Herniated Intervertebral Disc', '추간판탈출증', 'HIVD', '추간판 내부의 수핵이 섬유륜을 뚫고 나와 신경을 압박하여 통증을 유발하는 질환입니다. 흔히 \'디스크\'라고 불립니다.'),
                                                                         (402, 'Myelogram', '척수조영술', NULL, '척수강 내에 조영제를 주입한 후 X선 촬영을 하여 척수와 신경의 이상을 진단하는 검사입니다.'),
                                                                         (403, 'Osteoporosis', '골다공증', NULL, '뼈의 양이 감소하고 질이 약해져서 작은 충격에도 쉽게 골절이 일어나는 상태입니다.'),
                                                                         (404, 'Kyphoplasty', '척추후만성형술', NULL, '압박 골절된 척추뼈에 풍선을 넣어 찌그러진 뼈를 복원한 후 골 시멘트를 주입하는 시술입니다.'),
                                                                         (405, 'Hallux Valgus', '무지외반증', NULL, '엄지발가락이 두 번째 발가락 쪽으로 심하게 휘어지고 관절이 돌출되는 변형입니다.'),
                                                                         (406, 'Laminectomy', '척추후궁절제술', NULL, '척추관 협착증 등에서 신경을 압박하는 척추후궁(뼈의 일부)을 제거하여 신경 압박을 해소하는 수술입니다.'),
                                                                         (407, 'Colle\'s Fracture', '콜리스 골절', NULL, '손목 관절 부근의 노뼈(요골) 끝부분에서 발생하는 가장 흔한 유형의 손목 골절입니다.'),
  (408, 'Reduction', '정복(술)', NULL, '골절되거나 탈구된 뼈를 원래의 해부학적 위치로 되돌려 맞추는 시술입니다.'),
  (409, 'Paraplegia', '양측마비, 하반신마비', NULL, '척수 손상 등으로 인해 양쪽 다리의 감각이나 운동 기능이 상실된 상태입니다.'),
  (410, 'Total Hip Replacement', '고관절전치환술', 'THR', '손상된 고관절(엉덩관절)을 제거하고 인공관절로 대체하는 수술입니다.'),
  (411, 'Total Knee Replacement', '슬관절전치환술', 'TKR', '손상된 슬관절(무릎관절)의 일부 또는 전체를 인공관절로 대체하는 수술입니다.'),
  (412, 'Osteopathy', '골병증, 정골요법', NULL, '뼈에 발생하는 질환을 총칭하는 용어 또는 근골격계를 중심으로 진단하고 치료하는 대체의학의 한 분야를 의미합니다.'),
  (413, 'Osteoplasty', '골성형술', NULL, '뼈의 모양을 바꾸거나 결손 부위를 재건하는 외과적 수술입니다.'),
  (414, 'Osteomyelitis', '골수염', NULL, '뼈 조직에 세균 등이 감염되어 염증이 발생하는 질환입니다.'),
  (415, 'Flexion', '굽힘', NULL, '관절의 각도를 줄이는 움직임, 즉 관절을 구부리는 동작입니다.'),
  (416, 'Rotator Cuff Injury', '회전근개손상', NULL, '어깨 관절을 감싸고 있는 4개의 근육 및 힘줄(회전근개)에 염증이나 파열이 생긴 상태입니다.'),
  (417, 'Polymyositis', '다발근육염', NULL, '여러 근육에 염증이 생겨 근력이 약화되는 자가면역질환입니다.'),
  (418, 'Myasthenia Gravis', '중증근무력증', 'MG', '신경과 근육 사이의 신호 전달 장애로 인해 근육이 쉽게 피로해지고 약해지는 질환입니다.'),
  (419, 'Chondrocyte', '연골세포', NULL, '성숙한 연골 조직을 구성하고 유지하는 주요 세포입니다.'),
  (420, 'Chondroblast', '연골모세포', NULL, '연골을 형성하는 세포로, 연골기질을 생성한 후 연골세포가 됩니다.'),
  (421, 'Periosteum', '골막, 뼈막', NULL, '뼈의 가장 바깥쪽을 감싸는 막으로, 뼈를 보호하고 혈관과 신경을 공급하며 뼈의 성장과 회복에 관여합니다.'),
  (422, 'Bone Marrow', '골수', NULL, '뼈의 내부에 있는 부드러운 조직으로, 혈액세포(적혈구, 백혈구, 혈소판)를 생성합니다.'),
  (423, 'Coccyx', '꼬리뼈', NULL, '척추의 가장 끝부분에 위치한 3~5개의 작은 뼈들로 구성된 구조입니다.'),
  (424, 'Ribs', '갈비뼈, 늑골', NULL, '흉강을 둘러싸고 내부 장기를 보호하는 활 모양의 뼈입니다.'),
  (425, 'Femur', '넙다리뼈, 대퇴골', NULL, '인체에서 가장 길고 강한 뼈로, 허벅지를 구성합니다.'),
  (426, 'Patella', '무릎뼈, 슬개골', NULL, '무릎 관절 앞쪽에 위치한 삼각형 모양의 뼈로, 무릎을 보호합니다.'),
  (427, 'Tibia', '정강뼈, 경골', NULL, '종아리를 형성하는 두 개의 뼈 중 더 크고 안쪽에 위치한 뼈입니다.'),
  (428, 'Scapula', '어깨뼈, 견갑골', NULL, '등 위쪽에 위치한 삼각형 모양의 납작한 뼈로, 팔과 몸통을 연결합니다.'),
  (429, 'Sacrum', '엉치뼈, 천골', NULL, '척추의 아랫부분과 골반의 뒤쪽 벽을 형성하는 삼각형 모양의 뼈입니다.'),
  (430, 'Ilium', '엉덩뼈, 장골', NULL, '골반을 구성하는 세 뼈 중 가장 크고 위쪽에 위치한 뼈입니다.'),
  (431, 'Arthroscopy', '관절경 검사/수술', NULL, '작은 절개를 통해 관절 내부에 카메라(관절경)를 삽입하여 진단하거나 수술하는 방법입니다.'),
  (432, 'Osteoarthritis', '골관절염', 'OA', '관절 연골이 마모되어 통증과 변형을 유발하는 퇴행성 관절 질환입니다.'),
  (433, 'Rheumatoid Arthritis', '류마티스성 관절염', 'RA', '면역체계가 자신의 관절을 공격하여 염증을 일으키는 자가면역질환입니다.'),
  (434, 'Ligament', '인대', NULL, '뼈와 뼈를 연결하여 관절을 안정시키는 강한 섬유 조직입니다.'),
  (435, 'Tendon', '힘줄, 건', NULL, '근육과 뼈를 연결하여 근육의 힘을 전달하는 섬유 조직입니다.'),
  (436, 'Carpal Tunnel Syndrome', '수근관증후군', 'CTS', '손목의 수근관이 좁아져 정중신경이 눌리면서 손과 손가락에 통증, 저림 증상이 나타나는 질환입니다.'),
  (437, 'Arthralgia', '관절통', NULL, '관절 부위에 나타나는 통증을 의미합니다.'),
  (438, 'Dislocation', '탈구', NULL, '관절을 이루는 뼈가 정상 위치에서 완전히 벗어난 상태입니다.'),
  (439, 'Subluxation', '부분탈구, 아탈구', NULL, '관절을 이루는 뼈가 정상 위치에서 불완전하게 벗어난 상태입니다.'),
  (440, 'Ankylosing Spondylitis', '강직척추염', 'AS', '척추에 염증이 생기고 점차 굳어 움직임이 둔해지는 류마티스성 질환입니다.'),
  (441, 'Anterior Cruciate Ligament', '전방십자인대', 'ACL', '무릎 관절 중앙에서 정강뼈가 넙다리뼈보다 앞으로 밀리는 것을 막는 중요한 인대입니다.'),
  (442, 'Medial Collateral Ligament', '내측측부인대', 'MCL', '무릎 관절의 안쪽에서 관절의 안정성을 유지하는 인대입니다.'),
  (443, 'Posterior Cruciate Ligament', '후방십자인대', 'PCL', '무릎 관절 중앙에서 정강뼈가 넙다리뼈보다 뒤로 밀리는 것을 막는 인대입니다.'),
  (444, 'Range of Motion', '관절가동범위', 'ROM', '특정 관절이 움직일 수 있는 최대한의 각도 범위를 의미합니다.'),
  (445, 'Synovial Bursa', '윤활주머니, 활액낭', NULL, '관절 주변에서 마찰을 줄여주는 액체(활액)가 담긴 주머니입니다.'),
  (446, 'Synovial Sheath', '윤활집, 활액초', NULL, '힘줄을 둘러싸서 마찰을 줄이고 보호하는 윤활주머니와 유사한 구조입니다.'),
  (447, 'Simple Joint', '단순관절', NULL, '두 개의 뼈만으로 이루어진 관절입니다.'),
  (448, 'Complex Joint', '복합관절', NULL, '세 개 이상의 뼈 또는 관절원반 등이 포함된 복잡한 구조의 관절입니다.'),
  (449, 'Articular Surface', '관절면', NULL, '관절에서 서로 맞닿는 뼈의 표면으로, 보통 연골로 덮여 있습니다.'),
  (450, 'Articular Tubercle', '관절결절', NULL, '관절 부근에 있는 작은 뼈의 융기(돌출 부위)를 말합니다.'),
  (451, 'Joint', '관절', NULL, '두 개 이상의 뼈가 서로 연결되는 부분으로, 움직임을 가능하게 합니다.'),
  (452, 'Respiratory System', '호흡계통', NULL, '산소를 들이마시고 이산화탄소를 배출하는 호흡 과정에 관여하는 기관들의 모임입니다.'),
  (453, 'Respiratory Tract', '숨길, 기도', NULL, '공기가 폐로 들어오고 나가는 통로 전체를 의미합니다. (코, 인두, 후두, 기관, 기관지 등)'),
  (454, 'Nasal Bone', '코뼈, 비골', NULL, '코의 윗부분, 즉 콧등을 형성하는 한 쌍의 뼈입니다.'),
  (455, 'Nasal Cavity', '코안, 비강', NULL, '코의 안쪽 공간으로, 공기를 데우고 습도를 조절하며 이물질을 거르는 역할을 합니다.'),
  (456, 'Nasal Concha', '코선반, 비갑개', NULL, '코안의 공기 흐름을 조절하고 표면적을 넓히는 선반 모양의 뼈 구조물입니다.'),
  (457, 'Sinus', '굴, 부비동', NULL, '코 주위 두개골 속에 있는 공기로 채워진 빈 공간입니다.'),
  (458, 'Pharynx', '인두', NULL, '코안과 입안의 뒤쪽에 위치한, 공기와 음식이 모두 지나가는 통로입니다.'),
  (459, 'Nasopharynx', '코인두, 비인두', NULL, '인두의 가장 윗부분으로 코안(비강)과 연결되는 부위입니다.'),
  (460, 'Larynx', '후두', NULL, '인두와 기관 사이에 위치하며, 발성 기능과 공기 통로 역할을 하는 기관입니다.'),
  (461, 'Epiglottis', '후두개, 후두덮개', NULL, '음식물이 기도로 들어가지 않도록 막아주는 후두 입구의 덮개 역할을 하는 연골입니다.'),
  (462, 'Vocal Ligament', '성대인대', NULL, '후두에 위치하며, 진동하여 목소리를 만드는 데 핵심적인 역할을 하는 인대입니다.'),
  (463, 'Trachea', '기관', NULL, '후두와 기관지를 연결하는 관 모양의 공기 통로입니다.'),
  (464, 'Tracheal Cartilage', '기관연골', NULL, '기관이 항상 열려 있도록 지지해주는 C자 모양의 연골 조직입니다.'),
  (465, 'Mediastinum', '종격, 가슴세로칸', NULL, '양쪽 폐 사이, 가슴 중앙에 위치한 공간으로 심장, 대혈관, 식도, 기관 등이 포함됩니다.'),
  (466, 'Lung', '폐, 허파', NULL, '가슴 안에 위치한 한 쌍의 장기로, 혈액과 공기 사이의 가스 교환을 담당하는 핵심 호흡기관입니다.'),
  (467, 'Bronchus', '기관지', NULL, '기관에서 양쪽 폐로 갈라지는 공기 통로입니다. / 기관지의 (형용사)(Bronchial)'),
  (468, 'Bronchioles', '세기관지', NULL, '기관지가 폐 속에서 더 가늘게 갈라져 가장 작은 가지를 이루는 부분입니다.'),
  (469, 'Alveoli', '폐포', NULL, '세기관지 끝에 달린 포도송이 모양의 작은 공기주머니로, 실제 가스 교환이 일어나는 부위입니다.'),
  (470, 'Pleura', '가슴막, 흉막', NULL, '폐와 가슴 안쪽 벽을 덮고 있는 두 겹의 얇은 막입니다.'),
  (471, 'Pleural Space', '가슴막공간', NULL, '폐를 싸고 있는 두 겹의 가슴막 사이에 존재하는 잠재적인 공간입니다.'),
  (472, 'Pneumonocyte', '폐세포', NULL, '폐포를 구성하는 세포를 의미합니다.'),
  (473, 'Ventilation', '환기', NULL, '폐 안팎으로 공기가 이동하는 과정, 즉 숨을 쉬는 행위를 말합니다.'),
  (474, 'Inspiration', '들숨, 흡기', NULL, '공기를 폐 안으로 들이마시는 과정입니다.'),
  (475, 'Expiration', '날숨, 호기', NULL, '폐에서 공기를 밖으로 내쉬는 과정입니다.'),
  (476, 'Eupnea', '정상호흡', NULL, '안정 상태에서의 편안하고 정상적인 호흡을 말합니다.'),
  (477, 'Apnea', '무호흡', NULL, '일시적으로 호흡이 정지된 상태입니다.'),
  (478, 'Tachypnea', '빈호흡', NULL, '호흡수가 비정상적으로 빠른 상태입니다.'),
  (479, 'Dyspnea', '호흡곤란', NULL, '주관적으로 숨쉬기가 어렵거나 불편하게 느껴지는 증상입니다.'),
  (480, 'Dyspnea on Exertion', '운동 시 호흡곤란', 'DOE', '평소에는 괜찮다가 운동이나 신체 활동 시에만 나타나는 호흡곤란입니다.'),
  (481, 'Shortness of Breath', '숨참', 'SOB', '호흡곤란과 유사한 의미로, 숨이 가쁘거나 짧게 느껴지는 증상입니다.'),
  (482, 'Hyperventilation', '과다호흡, 과환기', NULL, '필요 이상으로 빠르거나 깊게 호흡하여 혈중 이산화탄소 농도가 낮아지는 상태입니다.'),
  (483, 'Hypoventilation', '환기저하', NULL, '호흡이 비정상적으로 얕거나 느려져 혈중 이산화탄소 농도가 높아지는 상태입니다.'),
  (484, 'Rales (Crackles)', '나음, 수포음', NULL, '주로 들숨 시 \'빠직\'하는 소리가 들리며, 폐포에 액체가 있을 때 나는 비정상적인 호흡음입니다.'),
  (485, 'Rhonchi', '건성수포음', NULL, '기도에 가래 등 분비물이 많을 때 나는 \'그르렁\'거리는 거친 호흡음입니다.'),
  (486, 'Wheeze', '천명, 쌕쌕거림', NULL, '기도가 좁아졌을 때 공기가 통과하면서 나는 \'휘이\' 또는 \'색색\'거리는 소리입니다.'),
  (487, 'Pleural Friction Rub', '가슴막마찰음', NULL, '흉막에 염증이 생겨 두 겹의 막이 서로 마찰될 때 나는 \'뽀드득\'거리는 소리입니다.'),
  (488, 'Hypoxia', '저산소증', NULL, '신체 조직에 산소 공급이 부족한 상태를 말합니다.'),
  (489, 'Oxygenation', '산소공급, 산소화', NULL, '혈액이나 조직에 산소를 공급하는 과정입니다.'),
  (490, 'Respiratory Rate', '호흡수', 'RR', '1분 동안 숨을 쉬는 횟수를 말합니다.'),
  (491, 'Sputum', '객담, 가래', NULL, '호흡기에서 나오는 점액성 분비물입니다.'),
  (492, 'Secretion', '분비(물)', NULL, '샘이나 세포에서 물질이 생성되어 방출되는 것, 또는 그 물질 자체를 말합니다.'),
  (493, 'Sore Throat', '인후통', NULL, '목구멍, 특히 인두나 후두 부위의 통증을 말합니다.'),
  (494, 'Hiccup', '딸꾹질', NULL, '횡격막의 불수의적인 경련으로 인해 나타나는 현상입니다.'),
  (495, 'Chest Pain', '가슴통증, 흉통', NULL, '가슴 부위에서 느껴지는 통증이나 불편감을 말합니다.'),
  (496, 'Cyanosis', '청색증', NULL, '혈액 내 산소가 부족하여 피부나 점막이 푸르스름하게 변하는 증상입니다.'),
  (497, 'Choking', '숨막힘, 질식', NULL, '이물질 등으로 기도가 막혀 호흡을 할 수 없는 상태입니다.'),
  (498, 'Snore', '코골이', NULL, '수면 중 공기가 좁아진 기도를 통과하면서 나는 소리입니다.'),
  (499, 'Barrel Chest', '술통형 가슴', NULL, '만성 폐기종 등에서 폐가 과도하게 팽창하여 가슴이 술통처럼 둥글게 변한 모양입니다.'),
  (500, 'Upper Respiratory Infection', '상기도 감염', 'URI', '코, 인두, 후두 등 상부 호흡기에 바이러스나 세균이 감염된 것으로, 흔히 \'감기\'라고 합니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
  (501, 'Rhinitis', '비염', NULL, '코안(비강) 점막에 염증이 생긴 상태입니다.'),
  (502, 'Pharyngitis', '인두염', NULL, '인두에 염증이 발생한 상태입니다.'),
  (503, 'Tonsillitis', '편도염', NULL, '목젖 양쪽에 있는 구개편도에 염증이 생긴 것입니다.'),
  (504, 'Laryngitis', '후두염', NULL, '후두에 염증이 발생한 상태로, 목소리가 쉬는 증상이 특징적입니다.'),
  (505, 'Bronchitis', '기관지염', NULL, '기관지에 염증이 생긴 상태입니다.'),
  (506, 'Asthma', '천식', NULL, '특정 자극에 기도가 과민반응하여 좁아지고 호흡곤란, 기침 등이 반복되는 만성 질환입니다.'),
  (507, 'Chronic Obstructive Pulmonary Disease', '만성 폐쇄성 폐질환', 'COPD', '유해 가스 흡입 등으로 폐에 염증이 생겨 공기 흐름이 점차 제한되는 질환입니다.'),
  (508, 'Bronchiectasis', '기관지확장증', NULL, '기관지 벽이 손상되어 비정상적으로 영구히 늘어난 상태입니다.'),
  (509, 'Atelectasis', '무기폐', NULL, '폐의 일부가 허탈되어 공기가 들어가지 못하는 상태, 즉 폐가 쭈그러든 상태를 말합니다.'),
  (510, 'Emphysema', '폐기종', NULL, '폐포벽이 파괴되어 폐포가 비정상적으로 커지고 가스 교환 기능이 저하되는 질환입니다.'),
  (511, 'Pneumonia', '폐렴', NULL, '세균, 바이러스, 곰팡이 등에 의해 폐 실질에 염증이 생기는 질환입니다.'),
  (512, 'Community-Acquired Pneumonia', '지역사회획득 폐렴', 'CAP', '병원 외부의 일상적인 사회 환경에서 감염된 폐렴을 말합니다.'),
  (513, 'Interstitial Lung Disease', '간질성 폐질환', 'ILD', '폐포와 폐포 사이의 벽(간질)에 염증이나 섬유화가 발생하는 질환군을 통칭합니다.'),
  (514, 'Pulmonary Abscess', '폐농양', NULL, '폐 조직이 파괴되면서 고름(농)이 차 있는 공간이 형성된 것입니다.'),
  (515, 'Pulmonary Edema', '폐부종', NULL, '폐포 안에 비정상적으로 많은 양의 체액이 축적되어 호흡곤란을 유발하는 상태입니다.'),
  (516, 'Pulmonary Embolism', '폐색전증', 'PE', '혈전(피떡)이 폐동맥을 막아 발생하는 질환으로, 심각한 호흡곤란을 유발할 수 있습니다.'),
  (517, 'Pleurisy (Pleuritis)', '흉막염, 가슴막염', NULL, '폐를 둘러싼 흉막에 염증이 생긴 상태입니다.'),
  (518, 'Pleural Effusion', '흉막삼출, 흉수', NULL, '흉막강 내에 비정상적으로 액체가 고이는 상태입니다.'),
  (519, 'Hydrothorax', '물가슴증, 수흉', NULL, '흉막강 내에 림프액이나 혈장이 아닌 맑은 액체(장액)가 고인 상태입니다.'),
  (520, 'Hemothorax', '혈흉', NULL, '흉막강 내에 혈액이 고인 상태입니다.'),
  (521, 'Pyothorax', '가슴고름(증), 농흉', NULL, '흉막강 내에 고름(농)이 고인 상태입니다.(Empyema)'),
  (522, 'Pneumothorax', '기흉', NULL, '흉막강 내에 공기가 차서 폐가 허탈되는 상태입니다.'),
  (523, 'Pneumonoconiosis', '폐먼지증, 진폐증', NULL, '분진을 장기간 흡입하여 폐에 축적되어 발생하는 직업성 폐 질환입니다.'),
  (524, 'Respiratory Acidosis', '호흡성 산증', NULL, '환기 저하로 인해 체내에 이산화탄소가 축적되어 혈액이 산성화되는 상태입니다.'),
  (525, 'Adult Respiratory Distress Syndrome', '성인호흡곤란증후군', 'ARDS', '심한 폐 손상으로 인해 급성으로 발생하는 심각한 호흡부전 상태입니다. (최근에는 급성호흡곤란증후군으로 통칭)'),
  (526, 'Pulmonary Function Test', '폐기능 검사', 'PFT', '폐활량, 공기 유속 등을 측정하여 폐의 전반적인 기능을 평가하는 검사입니다.'),
  (527, 'Laryngoscopy', '후두경검사', NULL, '후두경이라는 기구를 이용해 후두 내부를 직접 관찰하는 검사입니다.'),
  (528, 'Bronchoscopy', '기관지경 검사', NULL, '기관지 내시경을 이용해 기관 및 기관지 내부를 관찰하거나 조직 검사를 하는 검사입니다.'),
  (529, 'Thoracentesis', '흉강천자', NULL, '진단이나 치료 목적으로, 주사기를 이용해 흉막강 내의 액체를 뽑아내는 시술입니다.'),
  (530, 'Adenoidectomy', '아데노이드편도절제술', NULL, '코인두에 위치한 아데노이드를 외과적으로 제거하는 수술입니다.'),
  (531, 'Pneumonectomy', '폐절제술', NULL, '한쪽 폐 전체를 외과적으로 제거하는 수술입니다.'),
  (532, 'Lobectomy', '엽절제술', NULL, '폐를 구성하는 여러 엽(lobe) 중 하나를 제거하는 수술입니다.'),
  (533, 'Thoracostomy', '가슴관삽입술', NULL, '기흉이나 혈흉 시, 흉막강에 튜브(가슴관)를 삽입하여 공기나 액체를 배출하는 시술입니다.'),
  (534, 'Tracheotomy', '기관절개술', NULL, '목 앞부분을 절개하여 기관에 직접 통로를 만들어 호흡을 돕는 수술입니다.'),
  (535, 'Pulmonary Drainage', '폐배액', NULL, '폐나 흉막강 내의 비정상적인 액체나 공기를 체외로 배출시키는 것을 말합니다.'),
  (536, 'Oxygen Therapy', '산소요법', NULL, '저산소증 환자에게 산소를 공급하여 혈중 산소 농도를 높이는 치료입니다.'),
  (537, 'Inhalation', '흡입', NULL, '약물을 기체나 미세한 입자 형태로 만들어 기도로 직접 투여하는 방법입니다.'),
  (538, 'Nebulizer', '분무기, 연무기', NULL, '액체 약물을 미세한 안개 형태로 만들어 환자가 쉽게 흡입할 수 있도록 돕는 의료기기입니다.'),
  (539, 'Mechanical Ventilation', '기계적 환기', NULL, '자발 호흡이 불가능하거나 불충분한 환자의 호흡을 인공호흡기를 이용해 보조하는 것입니다.'),
  (540, 'Continuous Positive Airway Pressure', '지속기도양압', 'CPAP', '수면 무호흡증 등에서, 지속적으로 일정한 압력의 공기를 기도로 불어넣어 기도가 막히는 것을 방지하는 치료법입니다.'),
  (541, 'Positive End-Expiratory Pressure', '호기말 양압', 'PEEP', '기계 환기 시 날숨이 끝난 후에도 폐에 일정한 양압을 유지시켜 폐포의 허탈을 방지하는 기능입니다.'),
  (542, 'Pulmonology', '호흡기내과', 'PM', '폐, 기관지 등 호흡기계 질환을 전문적으로 진단하고 치료하는 내과의 한 분과입니다.'),
  (543, 'Digestive System', '소화계통', NULL, '음식물의 섭취, 소화, 흡수, 배설에 관여하는 모든 기관을 통칭합니다.'),
  (544, 'Gastrointestinal Tract', '위창자길, 위장관', 'GI tract', '입에서부터 항문까지 이어지는 소화기관의 긴 통로를 말합니다.'),
  (545, 'Oral Cavity', '입안, 구강 / 입', NULL, '소화관이 시작되는 부분으로, 음식물을 섭취하고 저작운동을 하는 곳입니다.(Mouth)'),
  (546, 'Tongue', '혀', NULL, '입안에 있는 근육 기관으로, 맛을 느끼고 음식물을 섞으며 발음을 돕습니다.'),
  (547, 'Gingiva', '잇몸, 치은', NULL, '치아의 뿌리를 덮고 있는 구강 점막의 일부입니다.'),
  (548, 'Palate', '입천장, 구개', NULL, '입안의 위쪽 벽을 이루는 구조로, 딱딱한 경구개와 물렁한 연구개로 나뉩니다.'),
  (549, 'Soft Palate', '물렁입천장, 연구개', NULL, '입천장의 뒤쪽 부드러운 부분입니다.'),
  (550, 'Salivary Gland', '침샘', NULL, '침(타액)을 생성하고 분비하는 샘입니다.'),
  (551, 'Pharynx', '인두', NULL, '입안과 식도 사이에 위치하며 음식물과 공기가 지나가는 공동 통로입니다.'),
  (552, 'Esophagus', '식도', NULL, '인두와 위를 연결하는 근육으로 된 관으로, 음식물을 위로 운반합니다.'),
  (553, 'Abdomen', '복부', NULL, '가슴과 골반 사이에 위치한 신체 부위로, 여러 소화기관이 들어있습니다.'),
  (554, 'Stomach', '위', NULL, '식도와 십이지장 사이에 있는 주머니 모양의 장기로, 음식물을 소화시킵니다.'),
  (555, 'Pylorus', '날문, 유문', NULL, '위에서 십이지장으로 이어지는 좁은 통로 부분입니다.'),
  (556, 'Mucosa', '점막', NULL, '소화관 등 내부 장기의 표면을 덮고 있는 촉촉한 막입니다.'),
  (557, 'Submucosa', '점막밑층, 점막하층', NULL, '점막과 근육층 사이에 위치한 결합조직층입니다.'),
  (558, 'Small Intestine', '작은창자, 소장', NULL, '위와 큰창자 사이에 위치하며, 영양소 흡수가 주로 일어나는 소화관입니다.'),
  (559, 'Duodenum', '샘창자, 십이지장', NULL, '작은창자의 첫 부분으로, 위와 연결됩니다.'),
  (560, 'Jejunum', '빈창자, 공장', NULL, '작은창자의 중간 부분으로, 십이지장과 돌창자 사이에 있습니다.'),
  (561, 'Ileum', '돌창자, 회장', NULL, '작은창자의 마지막 부분으로, 큰창자와 연결됩니다.'),
  (562, 'Villus', '융모', NULL, '작은창자 내벽에 있는 수많은 미세한 돌기로, 영양소 흡수 표면적을 넓힙니다.'),
  (563, 'Enterocyte', '창자세포, 장세포', NULL, '창자의 내벽을 구성하는 세포로, 영양소 흡수를 담당합니다.'),
  (564, 'Large Intestine', '큰창자, 대장', NULL, '작은창자 끝에서 항문까지 이어지며, 수분을 흡수하고 대변을 형성합니다.'),
  (565, 'Cecum', '막창자, 맹장', NULL, '큰창자가 시작되는 부분에 위치한 주머니 모양의 구조입니다.'),
  (566, 'Vermiform Appendix', '막창자꼬리, 충수', NULL, '막창자 끝에 붙어있는 작은 꼬리 모양의 기관입니다.'),
  (567, 'Colon', '잘록창자, 결장', NULL, '큰창자의 대부분을 차지하는 부분으로, 상행/횡행/하행/구불결장으로 나뉩니다.'),
  (568, 'Transverse Colon', '가로잘록창자, 횡행결장', NULL, '잘록창자 중 복부를 가로질러 주행하는 부분입니다.'),
  (569, 'Sigmoid Colon', '구불잘록창자, S상결장', NULL, '잘록창자의 마지막 부분으로, 직장과 연결되는 S자 모양의 부분입니다.'),
  (570, 'Rectum', '곧창자, 직장', NULL, '큰창자의 끝부분으로, 대변이 배설되기 전에 저장되는 곳입니다.'),
  (571, 'Anus', '항문', NULL, '소화관의 가장 마지막 부분으로, 대변이 배출되는 통로입니다.'),
  (572, 'Bowel', '창자, 장', NULL, '위 아래에 있는 소화관 부분, 즉 소장과 대장을 통칭합니다.'),
  (573, 'Liver', '간', NULL, '인체에서 가장 큰 장기로, 여러 대사 작용, 해독 작용, 쓸개즙 생성 등을 담당합니다.'),
  (574, 'Gallbladder', '쓸개, 담낭', NULL, '간 아래에 붙어있는 작은 주머니로, 간에서 생성된 쓸개즙을 저장하고 농축합니다.'),
  (575, 'Bile', '쓸개즙, 담즙', NULL, '간에서 생성되는 소화액으로, 지방의 소화와 흡수를 돕습니다.'),
  (576, 'Common Bile Duct', '온쓸개관, 총담관', 'CBD', '간과 쓸개에서 나온 쓸개즙이 십이지장으로 흘러 들어가는 공통 관입니다.'),
  (577, 'Pancreas', '이자, 췌장', NULL, '위 뒤쪽에 위치하며, 소화효소와 인슐린 등 호르몬을 분비하는 기관입니다.'),
  (578, 'Digestion', '소화', NULL, '섭취한 음식물을 몸에 흡수할 수 있도록 잘게 분해하는 과정입니다.'),
  (579, 'Appetite', '식욕, 입맛', NULL, '음식을 먹고 싶어 하는 욕구를 말합니다.'),
  (580, 'Saliva', '침 / 침분비', NULL, '침샘에서 침이 생성되어 분비되는 과정 또는 그 침 자체를 말합니다.(Salivation)'),
  (581, 'Swallowing', '연하, 삼키기', NULL, '입안의 음식물을 인두를 거쳐 식도로 넘기는 동작입니다.'),
  (582, 'Bowel Habit', '배변습관', NULL, '대변을 보는 주기, 시간, 양상 등 개인의 습관을 말합니다.'),
  (583, 'Fasting', '공복, 절식', NULL, '일정 시간 동안 음식을 섭취하지 않은 상태를 말합니다.'),
  (584, 'Pepsin', '펩신 / 펩시노겐', NULL, '펩시노겐은 위에서 분비되는 단백질 분해효소의 비활성 형태로, 위산에 의해 펩신으로 활성화됩니다.(Pepsinogen)'),
  (585, 'Nausea', '오심, 욕지기', NULL, '토할 것처럼 속이 메슥거리는 불쾌한 느낌입니다.'),
  (586, 'Vomiting', '구토', NULL, '위의 내용물이 입을 통해 강력하게 뿜어져 나오는 현상입니다.'),
  (587, 'Brash', '가슴앓이, 속쓰림', NULL, '위산 역류 등으로 인해 가슴 부위가 타는 듯한 느낌을 받는 증상입니다.'),
  (588, 'Dyspepsia', '소화불량', NULL, '상복부의 통증이나 불편감이 주된 증상인 상태를 통칭합니다.'),
  (589, 'Dysphagia', '연하곤란, 삼킴곤란', NULL, '음식물을 삼키기 어렵거나 삼킬 때 통증을 느끼는 증상입니다.'),
  (590, 'Regurgitation', '역류', NULL, '소화되지 않은 음식물이나 위산이 식도를 거쳐 입으로 다시 올라오는 현상입니다.'),
  (591, 'Hiccup', '딸꾹질', NULL, '횡격막의 불수의적인 경련으로 인해 나타나는 현상입니다.'),
  (592, 'Diarrhea', '설사', NULL, '배변 횟수가 비정상적으로 증가하고 묽은 변을 보는 증상입니다.'),
  (593, 'Constipation', '변비', NULL, '배변 횟수가 적거나 배변이 힘든 상태입니다.'),
  (594, 'Hematemesis', '토혈', NULL, '상부 위장관 출혈로 인해 피를 토하는 증상입니다.'),
  (595, 'Hematochezia', '혈변배설', NULL, '선홍색의 피가 대변에 섞여 나오거나 대변 본 후에 나오는 증상으로, 주로 하부 위장관 출혈을 시사합니다.'),
  (596, 'Melena', '흑색변', NULL, '상부 위장관 출혈로 인해 혈액이 위산과 반응하여 변이 자장면 색처럼 검게 나오는 증상입니다.'),
  (597, 'Fecal Incontinence', '대변실금', NULL, '자신의 의지와 상관없이 대변이 배출되는 증상입니다.'),
  (598, 'Anorexia', '식욕부진', NULL, '음식을 먹고 싶은 욕구가 현저히 저하되거나 없는 상태입니다.'),
  (599, 'Dehydration', '탈수', NULL, '체내의 수분이 정상보다 부족해진 상태입니다.'),
  (600, 'Cachexia', '악액질', NULL, '암이나 만성질환으로 인해 체중 감소, 근육 소실, 식욕부진 등이 나타나는 심각한 전신 쇠약 상태입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
  (601, 'Jaundice', '황달', NULL, '혈액 내 빌리루빈 수치가 높아져 피부나 눈의 흰자위가 노랗게 변하는 증상입니다.'),
  (602, 'Ascites', '복수', NULL, '복강 내에 비정상적으로 많은 양의 액체가 고이는 상태입니다.'),
  (603, 'Gingivitis', '잇몸염, 치은염', NULL, '잇몸에 염증이 생긴 상태입니다.'),
  (604, 'Pharyngitis', '인두염', NULL, '인두 점막에 염증이 생긴 상태입니다.'),
  (605, 'Tonsillitis', '편도염', NULL, '구개편도에 염증이 발생한 질환입니다.'),
  (606, 'Gastritis', '위염', NULL, '위 점막에 염증이 생긴 상태입니다.'),
  (607, 'Gastroenteritis', '위장염, 위창자염', NULL, '위와 장에 동시에 염증이 발생한 질환입니다.'),
  (608, 'Gastric Ulcer', '위궤양', NULL, '위 점막이 손상되어 움푹 파인 상태입니다.'),
  (609, 'Duodenal Ulcer', '십이지장 궤양', NULL, '십이지장 점막이 손상되어 움푹 파인 상태입니다.'),
  (610, 'Gastroesophageal Reflux Disease', '위식도역류질환', 'GERD', '위산이나 위의 내용물이 식도로 역류하여 불편한 증상을 유발하는 질환입니다.'),
  (611, 'Esophageal Varix', '식도정맥류', NULL, '주로 간경변으로 인해 식도 정맥이 비정상적으로 부풀어 오른 상태로, 출혈 위험이 높습니다.'),
  (612, 'Enteritis', '창자염, 장염', NULL, '작은창자에 염증이 생긴 상태입니다.'),
  (613, 'Enterocolitis', '소장대장염', NULL, '작은창자와 큰창자에 동시에 염증이 생긴 상태입니다.'),
  (614, 'Ulcerative Colitis', '궤양성 대장염', 'UC', '대장 점막에 다발적인 궤양과 염증이 발생하는 만성 염증성 장질환입니다.'),
  (615, 'Crohn\'s Disease', '크론병', 'CD', '입에서 항문까지 소화관 전체에 걸쳐 염증이 발생할 수 있는 만성 염증성 장질환입니다.'),
                                                                         (616, 'Inflammatory Bowel Disease', '염증성 장질환', 'IBD', '궤양성 대장염과 크론병을 통칭하는 용어입니다.'),
                                                                         (617, 'Appendicitis', '충수염', NULL, '충수(막창자꼬리)에 염증이 발생한 상태입니다.'),
                                                                         (618, 'Hepatitis', '간염', NULL, '간세포 및 간 조직에 염증이 발생한 상태입니다.'),
                                                                         (619, 'Liver Cirrhosis', '간경변, 간경화', 'LC', '지속적인 간 손상으로 간이 섬유화되고 굳어져 기능이 저하되는 만성 간 질환입니다.'),
                                                                         (620, 'Hepatomegaly', '간비대', NULL, '간이 정상보다 비정상적으로 커진 상태입니다.'),
                                                                         (621, 'Hepatic Coma', '간성혼수', NULL, '심한 간 기능 저하로 인해 의식 변화가 나타나는 상태입니다.'),
                                                                         (622, 'Cholelithiasis', '담석증, 쓸개돌증', NULL, '쓸개(담낭)나 담관에 돌(결석)이 생기는 질환입니다.'),
                                                                         (623, 'Cholangitis', '담관염, 쓸개관염', NULL, '쓸개즙이 내려오는 길인 담관(쓸개관)에 염증이 생긴 상태입니다.'),
                                                                         (624, 'Pancreatitis', '췌장염, 이자염', NULL, '췌장(이자)에 염증이 발생한 질환입니다.'),
                                                                         (625, 'Peritonitis', '복막염, 배막염', NULL, '복강 내 장기를 감싸고 있는 복막(배막)에 염증이 생긴 상태입니다.'),
                                                                         (626, 'Intestinal Obstruction', '장폐색, 창자막힘', NULL, '장의 일부가 막혀 내용물이 통과하지 못하는 상태입니다.(Ileus)'),
                                                                         (627, 'Intussusception', '창자겹침증, 장중첩증', NULL, '장의 일부가 안쪽으로 말려 들어가는 질환으로, 주로 영유아에게서 발생합니다.'),
                                                                         (628, 'Hernia', '탈장', NULL, '신체 내 장기가 제 위치를 벗어나 다른 조직을 통해 돌출된 상태입니다.'),
                                                                         (629, 'Hemorrhoids', '치핵', NULL, '항문 주변의 정맥이 부풀어 오르고 늘어져 생기는 질환입니다.'),
                                                                         (630, 'Polyp', '용종, 폴립', NULL, '점막 표면 위로 돌출된 작은 혹 모양의 병변입니다.'),
                                                                         (631, 'Adenoma', '샘종, 선종', NULL, '분비샘을 구성하는 상피세포에서 기원한 양성 종양으로, 일부는 암으로 발전할 수 있습니다.'),
                                                                         (632, 'Malabsorption', '흡수장애', NULL, '소화된 영양소가 장에서 제대로 흡수되지 못하는 상태입니다.'),
                                                                         (633, 'Fistula', '샛길, 누공', NULL, '정상적으로는 연결되어 있지 않은 두 개의 장기나 신체 부위 사이에 비정상적인 통로가 생긴 것입니다.'),
                                                                         (634, 'Perforation', '천공', NULL, '위나 장 등 장기 벽에 구멍이 뚫리는 것입니다.'),
                                                                         (635, 'Upper Gastrointestinal Endoscopy', '상부위장관내시경', 'EGD', '내시경을 입을 통해 삽입하여 식도, 위, 십이지장을 관찰하는 검사입니다.'),
                                                                         (636, 'Colonoscopy', '대장내시경검사', NULL, '내시경을 항문을 통해 삽입하여 전체 대장 내부를 관찰하는 검사입니다.'),
                                                                         (637, 'Sigmoidoscopy', '구불창자내시경검사', NULL, '내시경으로 항문, 직장, 구불결장까지 관찰하는 검사입니다.'),
                                                                         (638, 'Endoscopic Retrograde Cholangiopancreatography', '내시경역행췌담관조영술', 'ERCP', '내시경과 방사선을 이용하여 담관과 췌관을 검사하고 치료하는 시술입니다.'),
                                                                         (639, 'Barium Enema', '바륨관장', NULL, '바륨이라는 조영제를 항문을 통해 주입한 후 X선 촬영을 하여 대장을 검사하는 방법입니다.'),
                                                                         (640, 'Paracentesis', '(복수)천자', NULL, '주사기를 이용해 복강 내에 고인 액체(복수)를 뽑아내는 시술입니다.'),
                                                                         (641, 'Biopsy', '생검, 조직검사', NULL, '진단을 위해 살아있는 조직의 일부를 채취하여 현미경으로 검사하는 것입니다.'),
                                                                         (642, 'Laparotomy', '개복술', NULL, '복벽을 절개하여 복강 내부를 직접 확인하거나 수술하는 것입니다.'),
                                                                         (643, 'Gastrectomy', '위절제술', NULL, '위의 일부 또는 전체를 외과적으로 제거하는 수술입니다.'),
                                                                         (644, 'Appendectomy', '충수절제술', NULL, '염증이 생긴 충수(막창자꼬리)를 외과적으로 제거하는 수술입니다.'),
                                                                         (645, 'Cholecystectomy', '담낭절제술, 쓸개절제술', NULL, '쓸개(담낭)를 외과적으로 제거하는 수술입니다.'),
                                                                         (646, 'Colostomy', '잘록창자창냄술, 결장루', NULL, '수술을 통해 복벽에 인공적인 항문(장루)을 만들어 대변을 배출하도록 하는 것입니다.'),
                                                                         (647, 'Ileostomy', '돌창자창냄술, 회장루', NULL, '작은창자의 끝부분인 돌창자(회장)를 복벽에 연결하여 인공 항문(장루)을 만드는 수술입니다.'),
                                                                         (648, 'Stoma', '(인공)루, 창냄', NULL, '수술을 통해 장기를 체외로 연결하여 만든 구멍을 말합니다. (예: 장루)'),
                                                                         (649, 'Gastric Gavage', '위영양', NULL, '코나 입을 통해 위에 관을 삽입하여 영양을 공급하는 방법입니다.'),
                                                                         (650, 'Gastric Lavage', '위세척', NULL, '관을 통해 위에 생리식염수 등을 주입하고 다시 빼내어 위 내부를 씻어내는 시술입니다.'),
                                                                         (651, 'Proton Pump Inhibitor', '프로톤펌프억제제', 'PPI', '위산 분비를 강력하게 억제하는 약물로, 위궤양, 역류성 식도염 등에 사용됩니다.'),
                                                                         (652, 'Abdomen', '복부', NULL, '가슴과 골반 사이에 위치한 신체 부위로, 여러 소화기관이 들어있습니다.'),
                                                                         (653, 'Aorta', '대동맥', NULL, '심장의 좌심실에서 나와 온몸으로 혈액을 보내는 가장 크고 굵은 동맥입니다.'),
                                                                         (654, 'Aortic Dissection', '대동맥박리', NULL, '대동맥의 내벽이 찢어져 혈액이 혈관벽의 층 사이로 흘러 들어가 대동맥이 분리되는 치명적인 상태입니다.'),
                                                                         (655, 'Arrhythmia', '부정맥', NULL, '심장 박동이 불규칙하거나 정상 범위를 벗어나는 상태입니다.'),
                                                                         (656, 'Arterial Blood Gas Analysis', '동맥혈 가스 분석', 'ABGA', '동맥혈을 채취하여 혈액 내 산소, 이산화탄소 농도 및 산성도(pH) 등을 분석하는 검사입니다.'),
                                                                         (657, 'Artery', '동맥', NULL, '심장에서 나가는 혈액이 흐르는 혈관입니다.'),
                                                                         (658, 'Atrial Fibrillation', '심방세동, 심방된떨림', 'AF', '심방이 불규칙하고 매우 빠르게 미세하게 떨리는 부정맥의 일종입니다.'),
                                                                         (659, 'Biopsy', '생검, 조직검사', 'Bx', '진단을 위해 살아있는 조직의 일부를 채취하여 현미경으로 검사하는 것입니다.'),
                                                                         (660, 'Blood', '혈액', NULL, '신체 조직에 산소와 영양분을 공급하고 노폐물을 운반하는 체액입니다.'),
                                                                         (661, 'Blood Pressure', '혈압', 'BP', '혈액이 혈관 벽에 미치는 압력입니다.'),
                                                                         (662, 'Bradycardia', '느린맥, 서맥', NULL, '심장 박동수가 분당 60회 미만으로 비정상적으로 느린 상태입니다.'),
                                                                         (663, 'Capillary', '모세혈관', NULL, '동맥과 정맥을 연결하는 매우 가는 혈관으로, 조직과 물질 교환이 일어납니다.'),
                                                                         (664, 'Cardiac Arrest', '심정지', NULL, '심장의 펌프 기능이 갑자기 멈추어 혈액 순환이 중단된 상태입니다.'),
                                                                         (665, 'Cardiac Tamponade', '심장눌림증, 심낭압전', NULL, '심장을 싸고 있는 막(심낭) 안에 액체가 고여 심장이 제대로 이완하지 못하고 압박받는 상태입니다.'),
                                                                         (666, 'Cardiology', '순환기내과', 'CM (Cardio)', '심장 및 혈관에 관련된 질환을 진단하고 치료하는 내과의 한 분과입니다.'),
                                                                         (667, 'Cardiomegaly', '심장비대', NULL, '심장이 비정상적으로 커진 상태입니다.'),
                                                                         (668, 'Cardiopulmonary Resuscitation', '심폐소생술', 'CPR', '심장 박동과 호흡이 멈춘 환자에게 인공적으로 혈액을 순환시키고 호흡을 돕는 응급 처치입니다.'),
                                                                         (669, 'Cardiovascular System', '심장혈관계통', 'CV system', '심장과 혈관으로 구성되어 혈액을 온몸으로 순환시키는 계통입니다.'),
                                                                         (670, 'Cardioversion', '(심장)율동전환', NULL, '약물이나 전기 충격을 이용해 비정상적인 심장 리듬을 정상으로 되돌리는 치료입니다.'),
                                                                         (671, 'Complete Blood Count', '전혈구 검사', 'CBC', '혈액 내 적혈구, 백혈구, 혈소판의 수와 상태를 분석하는 기본적인 혈액 검사입니다.'),
                                                                         (672, 'Computed Tomography', '전산화단층촬영술', 'CT', 'X선과 컴퓨터를 이용하여 신체의 단면 영상을 얻는 정밀 영상 검사입니다.'),
                                                                         (673, 'Constriction', '수축', NULL, '혈관이나 통로 등이 좁아지는 것을 의미합니다.'),
                                                                         (674, 'Coronary', '심장-, 관상-', NULL, '심장에 관련된 것을 의미하며, 특히 심장에 혈액을 공급하는 관상동맥을 지칭할 때 사용됩니다.'),
                                                                         (675, 'Coronary Artery Bypass Graft', '관상동맥우회술', 'CABG', '좁아진 관상동맥을 우회하는 새로운 혈관 통로를 만들어주는 수술입니다.'),
                                                                         (676, 'Coronary Artery Disease', '관상동맥질환', 'CAD', '심장에 혈액을 공급하는 관상동맥이 좁아지거나 막혀서 발생하는 질환을 총칭합니다.'),
                                                                         (677, 'Deep Vein Thrombosis', '심부정맥혈전증', 'DVT', '주로 다리의 깊은 부위 정맥에 혈전(피떡)이 생기는 질환입니다.'),
                                                                         (678, 'Electrocardiography', '심전도', 'EKG(ECG)', '심장의 전기적 활동을 그래프로 기록하여 심장 질환을 진단하는 검사입니다.'),
                                                                         (679, 'Embolism', '색전(증)', NULL, '혈전(피떡)이나 다른 이물질이 혈관을 타고 이동하다가 혈관을 막는 상태입니다.'),
                                                                         (680, 'Emergency Room', '응급실', 'ER', '응급 환자를 진료하고 처치하는 병원의 공간입니다.'),
                                                                         (681, 'Endocarditis', '심내막염', NULL, '심장의 가장 안쪽 막이나 심장 판막에 염증이나 감염이 생긴 질환입니다.'),
                                                                         (682, 'Esophagus', '식도', NULL, '인두와 위를 연결하는 근육으로 된 관으로, 음식물을 위로 운반합니다.'),
                                                                         (683, 'Heart Failure', '심부전', 'HF', '심장의 펌프 기능이 저하되어 신체에 필요한 혈액을 충분히 공급하지 못하는 상태입니다.'),
                                                                         (684, 'Hematocrit', '혈구용적률', 'Hct(HCT)', '전체 혈액 중 적혈구가 차지하는 부피의 비율입니다.'),
                                                                         (685, 'Hematemesis', '토혈', NULL, '상부 위장관 출혈로 인해 피를 토하는 증상입니다.'),
                                                                         (686, 'Hemoglobin', '혈색소', 'Hb', '적혈구 안에 있으며 산소와 결합하는 단백질입니다.'),
                                                                         (687, 'Hypertension', '고혈압', 'HTN', '혈압이 정상 범위보다 지속적으로 높은 상태입니다.'),
                                                                         (688, 'Hypotension', '저혈압', NULL, '혈압이 정상 범위보다 낮은 상태입니다.'),
                                                                         (689, 'Incision', '절개', NULL, '수술 등을 위해 피부나 조직을 자르는 것입니다.'),
                                                                         (690, 'Intensive Care Unit', '중환자실', 'ICU', '생명 유지를 위해 집중적인 치료와 감시가 필요한 환자를 위한 병실입니다.'),
                                                                         (691, 'Ischemia', '허혈', NULL, '혈관이 좁아지거나 막혀 특정 조직이나 장기로의 혈액 공급이 부족해진 상태입니다.'),
                                                                         (692, 'Laboratory', '검사, 검사실', 'Lab', '질병의 진단을 위해 혈액, 소변 등을 검사하는 곳 또는 그 검사 자체를 의미합니다.'),
                                                                         (693, 'Murmur', '(심장)잡음', NULL, '정상적인 심장 박동음 외에 혈액이 와류하면서 나는 비정상적인 소리입니다.'),
                                                                         (694, 'Myocardial Infarction', '심근경색', 'MI', '관상동맥이 막혀 심장 근육으로의 혈액 공급이 차단되어 심장 근육이 괴사하는 질환입니다.'),
                                                                         (695, 'Myocarditis', '심근염', NULL, '심장 근육 자체에 염증이 생긴 질환입니다.'),
                                                                         (696, 'Normal Sinus Rhythm', '정상 동리듬', 'NSR', '심장의 동방결절에서 시작되는 정상적이고 규칙적인 심장 박동입니다.'),
                                                                         (697, 'Nothing by Mouth', '금식', 'NPO', '검사나 수술 등을 위해 입으로 아무것도 섭취하지 않는 것을 의미합니다.'),
                                                                         (698, 'Operation', '수술', 'OP', '질병이나 외상을 치료하기 위해 환자의 몸을 절개하여 시술하는 외과적 처치입니다.'),
                                                                         (699, 'Perfusion', '관류', NULL, '조직이나 장기에 혈액이 공급되어 흐르는 것을 의미합니다.'),
                                                                         (700, 'Pericardiocentesis', '심장막천자, 심낭천자', NULL, '심낭에 고인 액체를 바늘로 뽑아내는 시술입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (701, 'Pericarditis', '심장막염, 심낭염', NULL, '심장을 싸고 있는 막인 심낭에 염증이 생긴 질환입니다.'),
                                                                         (702, 'Percutaneous Drainage', '경피적 배액술', 'PCD', '피부를 통해 관을 삽입하여 체내의 액체나 농양을 배출시키는 시술입니다.'),
                                                                         (703, 'Red Blood Cells', '적혈구', 'RBC', '혈액 내에서 산소를 운반하는 역할을 하는 혈구입니다.'),
                                                                         (704, 'Shock', '쇼크', NULL, '조직에 혈액이 제대로 공급되지 않아 세포 기능 장애를 일으키는 위급한 상태입니다.'),
                                                                         (705, 'Stenosis', '협착', NULL, '혈관이나 판막 등의 통로가 비정상적으로 좁아진 상태입니다.'),
                                                                         (706, 'Suture', '봉합', NULL, '수술 등에서 절개된 조직을 실로 꿰매는 것입니다.'),
                                                                         (707, 'Systemic Circulation', '온몸순환, 체순환', NULL, '혈액이 좌심실에서 나와 온몸을 거쳐 우심방으로 돌아오는 순환 과정입니다.'),
                                                                         (708, 'Tachycardia', '빠른맥, 빈맥', NULL, '심장 박동수가 분당 100회 이상으로 비정상적으로 빠른 상태입니다.'),
                                                                         (709, 'Tonsillectomy', '편도절제술', NULL, '목의 양쪽에 있는 편도를 외과적으로 제거하는 수술입니다.'),
                                                                         (710, 'Valvotomy', '판막절개술', NULL, '좁아진 심장 판막을 절개하여 넓혀주는 수술입니다.'),
                                                                         (711, 'Valvulectomy', '판막절제술', NULL, '심장 판막을 외과적으로 제거하는 수술입니다.'),
                                                                         (712, 'Valvuloplasty', '판막성형술', NULL, '손상되거나 기능이 저하된 심장 판막을 교정하는 수술입니다.'),
                                                                         (713, 'Valvular', '판막의', NULL, '심장 판막에 관련된 것을 의미하는 형용사입니다.'),
                                                                         (714, 'Vein', '정맥', NULL, '신체 각 부분의 혈액을 모아 심장으로 되돌아오는 혈관입니다.'),
                                                                         (715, 'Ventricular Fibrillation', '심실세동, 심실된떨림', 'VF', '심실이 불규칙하고 매우 빠르게 떨려 사실상 심장 펌프 기능이 소실된 치명적인 부정맥입니다.'),
                                                                         (716, 'Vessel', '혈관', NULL, '혈액이 흐르는 관으로, 동맥, 정맥, 모세혈관 등을 포함합니다.'),
                                                                         (717, 'White Blood Cell (Leukocyte)', '백혈구', 'WBC', '면역 기능을 담당하며 신체를 감염으로부터 보호하는 혈구입니다.'),
                                                                         (718, 'Within Normal Limits', '정상범위 내', 'WNL', '검사 결과나 환자의 상태가 정상적인 범위 안에 있음을 의미합니다.'),
                                                                         (719, 'Abdominal Aorta', '배대동맥', NULL, '대동맥 중 복강(배)을 지나는 부분입니다.'),
                                                                         (720, 'Achilles Tendon (Tendo calcaneus)', '아킬레스힘줄, 발꿈치힘줄', NULL, '장딴지 근육을 발뒤꿈치뼈에 연결하는 인체에서 가장 크고 강한 힘줄입니다.'),
                                                                         (721, 'Airway Pressure', '기도내압', NULL, '호흡 시 기도(숨길) 내에 걸리는 압력을 말합니다.'),
                                                                         (722, 'Amniotic Fluid', '양수', NULL, '양막 안에 차 있으며, 임신 기간 동안 태아를 보호하는 액체입니다.'),
                                                                         (723, 'Anastomotic Vessel', '연결혈관, 문합혈관', NULL, '두 개 이상의 혈관이 서로 연결되는 혈관을 말합니다.'),
                                                                         (724, 'Angina Pectoris', '협심증', NULL, '관상동맥이 좁아져 심장 근육에 산소 공급이 부족해지면서 발생하는 가슴 통증입니다.'),
                                                                         (725, 'Artificial Pacemaker', '인공심장박동기', NULL, '심장 박동이 비정상적으로 느린 환자의 심장에 전기 자극을 주어 정상 박동을 유지시키는 의료 기기입니다.'),
                                                                         (726, 'Arterial Oxygen Saturation', '동맥혈산소포화도', 'SpO₂/SaO₂', '동맥혈 내 헤모글로빈이 산소와 결합한 비율을 나타냅니다.'),
                                                                         (727, 'Arterial Oxygen Tension', '동맥혈산소분압', 'PaO₂', '동맥혈에 녹아있는 산소의 부분 압력으로, 폐의 가스 교환 능력을 평가하는 지표입니다.'),
                                                                         (728, 'Arterial Pressure', '동맥압', NULL, '동맥 내의 혈압을 의미합니다.'),
                                                                         (729, 'Ascending Aorta', '오름대동맥', NULL, '심장에서 시작되어 위로 올라가는 대동맥의 첫 부분입니다.'),
                                                                         (730, 'Atherosclerosis', '죽상경화증', NULL, '동맥 혈관 벽에 콜레스테롤 등이 쌓여 플라크(죽종)를 형성하고 혈관이 좁아지고 딱딱해지는 질환입니다.'),
                                                                         (731, 'Atrial Septal Defect', '심방중격결손', 'ASD', '좌심방과 우심방 사이의 벽(심방중격)에 구멍이 있는 선천성 심장 기형입니다.'),
                                                                         (732, 'Atrial Systole', '심방수축기', NULL, '심장의 수축 주기 중 심방이 수축하여 혈액을 심실로 보내는 시기입니다.'),
                                                                         (733, 'Atrioventricular Junctional Tachycardia', '방실경계 빠른맥', NULL, '심방과 심실의 경계부에서 비정상적인 전기 신호가 발생하여 맥박이 빨라지는 부정맥입니다.'),
                                                                         (734, 'Blood Flow', '혈류', NULL, '혈관 내에서 혈액이 흐르는 것을 말합니다.'),
                                                                         (735, 'Blood Pressure Fluctuation', '혈압변동', NULL, '혈압이 안정되지 않고 오르내리며 변하는 상태입니다.'),
                                                                         (736, 'Blood Urea Nitrogen', '혈액요소질소', 'BUN', '혈액 속에 포함된 요소 질소의 농도로, 주로 신장 기능을 평가하는 데 사용되는 혈액 검사 항목입니다.'),
                                                                         (737, 'Burning Sensation', '작열감, 타는 느낌', NULL, '피부나 신체 일부가 불에 타는 것처럼 뜨겁고 화끈거리는 느낌을 말합니다.'),
                                                                         (738, 'Capillary Pressure', '모세혈관압', NULL, '모세혈관 내의 혈압을 의미합니다.'),
                                                                         (739, 'Central Venous Pressure', '중심정맥압', 'CVP', '상대정맥 또는 우심방 근처의 압력으로, 체내 혈액량 및 심장 기능을 간접적으로 평가하는 지표입니다.'),
                                                                         (740, 'Cerebrospinal Fluid', '뇌척수액', 'CSF', '뇌와 척수를 둘러싸고 보호하며 영양을 공급하는 맑은 액체입니다.'),
                                                                         (741, 'Claudication', '파행증, 절뚝거림', NULL, '주로 동맥 경화로 다리 혈관이 좁아져, 걸을 때 다리에 통증이나 경련이 나타나고 쉬면 사라지는 증상입니다.'),
                                                                         (742, 'Collateral Circulation', '곁순환, 측부순환', NULL, '주된 혈관이 막혔을 때, 주위의 다른 작은 혈관들을 통해 혈액이 우회하여 흐르는 순환입니다.'),
                                                                         (743, 'Common Iliac Vein', '온엉덩정맥, 총장골정맥', NULL, '양쪽 다리와 골반에서 오는 혈액이 모여 하대정맥으로 이어지는 큰 정맥입니다.'),
                                                                         (744, 'Congestive Heart Failure', '울혈심부전', 'CHF', '심장 기능 저하로 인해 혈액이 원활하게 순환하지 못하고 폐나 전신에 울혈(정체)이 생기는 상태입니다.'),
                                                                         (745, 'Coronary Angiography', '관상동맥조영술', 'CAG', '조영제를 주입하고 X선 촬영을 하여 심장의 관상동맥을 검사하는 방법입니다.'),
                                                                         (746, 'Corpuscle', '소체', NULL, '혈구와 같이 혈액이나 림프에 떠다니는 작은 입자나 세포를 의미합니다.'),
                                                                         (747, 'Cusp', '첨판, 교두', NULL, '심장 판막을 이루는 얇은 막 조각이나 치아의 뾰족한 부분을 말합니다.'),
                                                                         (748, 'Cutaneous Vein', '피부정맥', NULL, '피부 바로 아래에 위치하여 눈으로 확인이 가능한 얕은 정맥입니다.'),
                                                                         (749, 'Deep Vein', '깊은정맥, 심부정맥', NULL, '신체 깊은 곳에서 동맥과 나란히 주행하는 정맥입니다.'),
                                                                         (750, 'Defibrillation', '제세동', NULL, '심실세동 등 치명적인 부정맥 발생 시, 심장에 전기 충격을 가해 정상 리듬으로 되돌리는 응급 처치입니다.'),
                                                                         (751, 'Diastole', '확장기 / 확장기의', NULL, '심장이 수축한 후 이완하여 혈액을 채우는 시기 / 또는 그 시기의 (형용사)입니다.(Diastolic)'),
                                                                         (752, 'Diastolic Pressure', '확장기압, 이완기압', NULL, '심장이 이완했을 때 혈관 내 압력으로, 혈압 측정 시 낮은 쪽의 숫자입니다.'),
                                                                         (753, 'Epigastric Pain', '명치통증, 심와부통', NULL, '상복부의 중심, 즉 명치 부위에 나타나는 통증입니다.'),
                                                                         (754, 'Extracellular Fluid', '세포바깥액, 세포외액', 'ECF', '세포의 바깥쪽에 존재하며 조직과 혈관을 채우고 있는 체액입니다.'),
                                                                         (755, 'Fetal Tachycardia', '태아 빠른맥', NULL, '태아의 심장 박동이 정상 범위보다 비정상적으로 빠른 상태입니다.'),
                                                                         (756, 'Flowmeter', '유량계 / 유량측정법', NULL, '액체나 기체의 흐름 속도나 양을 측정하는 기계 / 또는 그 측정 방법을 말합니다.(Flowmetry)'),
                                                                         (757, 'Fluid', '액, 액체', NULL, '흐르는 성질을 가진 물질로, 인체에서는 체액을 의미합니다.'),
                                                                         (758, 'Heart', '심장', NULL, '혈액을 온몸으로 펌프질하는 근육 기관입니다.'),
                                                                         (759, 'Hemopericardium', '혈심낭, 혈액심장막', NULL, '심장을 싸고 있는 막(심낭) 안에 혈액이 고인 상태입니다.'),
                                                                         (760, 'Hemostatic Failure', '지혈기능상실', NULL, '혈액 응고 과정에 문제가 생겨 출혈이 멈추지 않는 상태입니다.'),
                                                                         (761, 'Hydrostatic Pressure', '정수압', NULL, '정지 상태의 액체가 가하는 압력으로, 모세혈관에서 체액을 조직으로 밀어내는 힘으로 작용합니다.'),
                                                                         (762, 'Interstitial Fluid', '사이질액, 간질액', NULL, '조직 내 세포들 사이에 존재하는 체액입니다.'),
                                                                         (763, 'Ischemic Heart Disease', '허혈심장질환', 'IHD', '관상동맥 질환으로 인해 심장 근육으로의 혈액 공급이 부족해져 발생하는 질환들을 통칭합니다.'),
                                                                         (764, 'Left Ventricular Hypertrophy', '좌심실비후', 'LVH', '심장의 좌심실 벽이 비정상적으로 두꺼워지는 상태로, 고혈압 등이 원인이 될 수 있습니다.'),
                                                                         (765, 'Leukemia', '백혈병', NULL, '혈액세포를 만드는 골수에서 백혈구가 비정상적으로 증식하는 혈액암입니다.'),
                                                                         (766, 'Lymphatic Vessel', '림프관', NULL, '림프액이 흐르는 관으로, 면역 기능에 중요한 역할을 합니다.'),
                                                                         (767, 'Mitral Valvotomy', '승모판절개(술)', NULL, '좁아진 승모판을 절개하여 넓혀주는 수술입니다.'),
                                                                         (768, 'Negative Pressure', '음압', NULL, '대기압보다 낮은 압력을 의미합니다.'),
                                                                         (769, 'Normal Pressure', '정상압', NULL, '특정 기준에 맞는 정상 범위 내의 압력입니다.'),
                                                                         (770, 'Oncotic Pressure', '교질삼투압 / 삼투압', NULL, '삼투압은 농도가 다른 두 용액 사이에서 발생하는 압력이며, 교질삼투압은 그중 혈장 단백질에 의해 발생하는 삼투압을 특정합니다.(Osmotic Pressure)'),
                                                                         (771, 'Oxygen Saturation', '산소포화도', NULL, '혈액 내 헤모글로빈이 산소와 얼마나 결합하고 있는지를 나타내는 비율입니다.'),
                                                                         (772, 'Oxygen Tension', '산소분압', NULL, '혈액이나 조직에 녹아 있는 산소의 부분압을 의미합니다.'),
                                                                         (773, 'Palpitation', '두근거림', NULL, '자신의 심장 박동이 불규칙하거나 강하게 느껴지는 주관적인 증상입니다.'),
                                                                         (774, 'Pansystolic Murmur', '범수축기잡음', NULL, '심장 수축기 전체에 걸쳐서 들리는 심장 잡음입니다.'),
                                                                         (775, 'Paroxysmal Supraventricular Tachycardia', '발작성 심실위 빠른맥', 'PSVT', '갑작스럽게 발생하여 갑자기 멈추는, 심실 상부에서 기원하는 빠른 부정맥입니다.'),
                                                                         (776, 'Partial Pressure', '분압', NULL, '혼합 기체에서 각각의 기체가 나타내는 부분적인 압력입니다.'),
                                                                         (777, 'Percutaneous Transluminal Coronary Angioplasty', '경피적경혈관관상동맥확장술', 'PTCA', '피부를 통해 풍선 카테터를 삽입하여 좁아진 관상동맥을 넓히는 시술입니다.'),
                                                                         (778, 'Perfusion Pressure', '관류압', NULL, '장기나 조직에 혈액이 흐르도록 하는 압력 차이를 의미합니다.'),
                                                                         (779, 'Plasma', '혈장', NULL, '혈액에서 혈구를 제외한 맑은 액체 성분입니다.'),
                                                                         (780, 'Positive Pressure', '양압', NULL, '대기압보다 높은 압력을 의미합니다.'),
                                                                         (781, 'Premature Ventricular Contraction', '조기심실수축', 'PVC (VPC)', '심장의 정상적인 박동 외에 심실에서 비정상적인 전기 신호가 먼저 발생하여 심장이 예정보다 일찍 수축하는 부정맥입니다.'),
                                                                         (782, 'Pressure', '압력', NULL, '단위 면적당 작용하는 힘을 의미합니다.'),
                                                                         (783, 'Pulse', '맥박', NULL, '심장 박동에 의해 동맥이 주기적으로 팽창하는 현상입니다.'),
                                                                         (784, 'Pulse Pressure', '맥박압', NULL, '수축기 혈압과 확장기 혈압의 차이를 말합니다.'),
                                                                         (785, 'Reactivity', '반응성', NULL, '외부 자극에 대해 반응하는 성질이나 정도를 의미합니다.'),
                                                                         (786, 'Red Blood Corpuscle', '적혈구', 'RBC', '혈액 내에서 산소를 운반하는 역할을 하는 세포(혈구)입니다.'),
                                                                         (787, 'Regurgitant Murmur', '역류잡음', NULL, '심장 판막이 제대로 닫히지 않아 혈액이 역류할 때 나는 심장 잡음입니다.'),
                                                                         (788, 'Revascularization', '혈관재형성', NULL, '막히거나 좁아진 혈관에 새로운 혈류를 만들어주는 시술이나 수술을 통칭합니다.'),
                                                                         (789, 'Rheumatic Heart (Disease)', '류마티스심장(병)', 'RHD', '류마티스열의 합병증으로 인해 심장 판막 등이 손상되는 질환입니다.'),
                                                                         (790, 'Rheumatic Valvulitis', '류마티스판막염', NULL, '류마티스열에 의해 심장 판막에 염증이 생긴 상태입니다.'),
                                                                         (791, 'Right Bundle Branch Block', '우각차단', 'RBBB', '심장의 전기 전도 시스템 중 우각의 전달이 차단된 상태를 말합니다.'),
                                                                         (792, 'Septal Defect', '중격 결손', NULL, '심장의 좌우를 나누는 벽(중격)에 구멍(결손)이 있는 상태입니다.'),
                                                                         (793, 'Serous Fluid', '장액', NULL, '흉막, 복막 등 장막에서 분비되는 맑은 액체입니다.'),
                                                                         (794, 'Sinus Tachycardia', '굴빠른맥, 동성빈맥', NULL, '심장의 정상적인 박동 조율기인 동방결절의 흥분 빈도가 증가하여 생기는 빠른맥입니다.'),
                                                                         (795, 'Sinusoid', '굴모세혈관, 동양혈관', NULL, '간, 골수 등에서 볼 수 있는, 불규칙하고 확장된 형태의 모세혈관입니다.'),
                                                                         (796, 'Superficial Vein', '얕은정맥, 표재정맥', NULL, '피부 가까이에 위치한 정맥입니다.'),
                                                                         (797, 'Superior Gluteal Veins', '위볼기정맥, 상둔정맥', NULL, '볼기(엉덩이) 부위의 혈액을 모으는 정맥입니다.'),
                                                                         (798, 'Supraventricular Tachycardia', '심실위 빠른맥', 'SVT', '심실 상부(심방, 방실결절)에서 기원하는 모든 빠른 부정맥을 통칭합니다.'),
                                                                         (799, 'Surface Tension', '표면장력', NULL, '액체의 표면이 스스로 수축하여 가능한 한 작은 면적을 가지려는 힘입니다.'),
                                                                         (800, 'Synovial Fluid', '윤활액, 활액', NULL, '관절의 움직임을 부드럽게 하고 연골에 영양을 공급하는 액체입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (801, 'Systole', '수축기 / 수축기의', NULL, '심장이 혈액을 뿜어내기 위해 수축하는 시기 / 또는 그 시기의 (형용사)입니다.(Systolic)'),
                                                                         (802, 'Systolic Murmur', '수축기잡음', NULL, '심장이 수축하는 동안 들리는 심장 잡음입니다.'),
                                                                         (803, 'Tachyarrhythmia', '빠른부정맥, 빈맥성 부정맥', NULL, '심장 박동이 비정상적으로 빠른 모든 종류의 부정맥을 말합니다.'),
                                                                         (804, 'Tenesmus', '뒤무직, 이급후중', NULL, '변을 본 후에도 변이 남아있는 듯한 느낌이 들어 계속 화장실에 가고 싶은 증상입니다.'),
                                                                         (805, 'Tension', '긴장', NULL, '정신적 또는 물리적으로 팽팽하게 죄는 상태나 힘을 말합니다. (예: 심벽긴장도)'),
                                                                         (806, 'Thrombus', '혈전', NULL, '혈관 속에서 혈액이 굳어서 생긴 핏덩어리를 말합니다.'),
                                                                         (807, 'Transfusion', '수혈', NULL, '다른 사람의 혈액이나 혈액 성분을 환자에게 주입하는 치료법입니다.'),
                                                                         (808, 'Valvule', '(작은)판막 / 판막', NULL, '혈액이나 림프가 역류하지 않고 한 방향으로 흐르도록 하는 막 구조물입니다.(Valve)'),
                                                                         (809, 'Vasa Vasorum', '혈관벽혈관, 맥관벽혈관', NULL, '큰 혈관의 벽 자체에 영양을 공급하는 미세한 혈관입니다.'),
                                                                         (810, 'Vasovagal Syncope', '미주신경성실신', NULL, '극심한 감정적 스트레스나 통증 등으로 미주신경이 자극되어 일시적으로 의식을 잃는 현상입니다.'),
                                                                         (811, 'Vegetation', '증식물, 우종', NULL, '주로 심내막염에서 심장 판막 등에 세균 덩어리나 혈전이 사마귀처럼 자라난 것을 말합니다.'),
                                                                         (812, 'Venae Comitans', '동반정맥', NULL, '동맥과 나란히 주행하는 한 쌍의 정맥입니다.'),
                                                                         (813, 'Venous Valve', '정맥판막', NULL, '정맥 내에서 혈액이 심장 방향으로만 흐르도록 하는 판막입니다.'),
                                                                         (814, 'Ventricular Tachycardia', '심실빈맥', 'VT', '심실에서 비정상적으로 빠른 전기 신호가 발생하여 생기는 위험한 부정맥입니다.'),
                                                                         (815, 'Venule', '세정맥', NULL, '모세혈관에서 모인 혈액이 정맥으로 이어지는 작은 정맥입니다.'),
                                                                         (816, 'Wall Tension', '심벽긴장도', NULL, '심장 벽에 걸리는 긴장이나 스트레스를 의미합니다.'),
                                                                         (817, 'White Blood Corpuscle', '백혈구', 'WBC', '혈액 내에서 면역 기능을 담당하는 세포(혈구)입니다.'),
                                                                         (818, 'Abortion Rate', '유산율', NULL, '전체 임신 중 자연유산이나 인공유산이 차지하는 비율을 말합니다.'),
                                                                         (819, 'Adnexectomy', '자궁부속기절제술', NULL, '자궁의 부속 기관인 난소와 난관(자궁관)을 외과적으로 제거하는 수술입니다.'),
                                                                         (820, 'Amenorrhea', '무월경', NULL, '월경이 없는 상태로, 원발성과 속발성으로 나뉩니다.'),
                                                                         (821, 'Amniocentesis', '양수천자, 양막천자', NULL, '태아의 유전적 이상 등을 진단하기 위해 주사기로 산모의 복부를 통해 양수를 채취하는 산전 검사입니다.'),
                                                                         (822, 'Amniography', '양수조영술', NULL, '양수 내에 조영제를 주입하고 X선 촬영을 하여 태아의 윤곽을 보는 검사입니다.'),
                                                                         (823, 'Amnion', '양막', NULL, '임신 중 태아와 양수를 둘러싸고 있는 가장 안쪽의 얇은 막입니다.'),
                                                                         (824, 'Amnionitis', '양막염', NULL, '양막에 염증이 생긴 상태를 말합니다.'),
                                                                         (825, 'Amniotic Fluid', '양수', NULL, '양막 안에 차 있으며, 임신 기간 동안 태아를 보호하는 액체입니다.'),
                                                                         (826, 'Amniotic Fluid Index', '양수지수', 'AFI', '초음파를 이용해 양수의 양을 측정하는 지표입니다.'),
                                                                         (827, 'Amniotomy', '인공양막파열', NULL, '분만을 유도하거나 촉진하기 위해 인위적으로 양막을 터뜨리는 시술입니다.'),
                                                                         (828, 'Ampulla of Uterine Tube', '자궁관팽대, 난관팽대부', NULL, '자궁관(난관)에서 가장 넓은 부분으로, 주로 수정이 일어나는 장소입니다.'),
                                                                         (829, 'Artificial Fertilization', '인공수정', NULL, '남성의 정자를 채취하여 여성의 생식기 내로 직접 주입하여 수정을 유도하는 방법입니다.'),
                                                                         (830, 'Breast Cancer', '유방암', NULL, '유방 조직에 발생하는 악성 종양입니다.'),
                                                                         (831, 'Breech Presentation', '둔위, 볼기태위', NULL, '분만 시 태아의 머리가 아닌 엉덩이나 다리가 자궁 출구 쪽을 향하고 있는 태아의 자세입니다.'),
                                                                         (832, 'Bulb of Vestibule', '질어귀망울, 전정구', NULL, '질 입구 양쪽에 있는 한 쌍의 해면체 조직으로, 성적 흥분 시 혈액이 차서 팽창합니다.'),
                                                                         (833, 'Cephalic Presentation', '선진두부, 머리태위', NULL, '분만 시 태아의 머리가 자궁 출구 쪽을 향하고 있는 정상적인 태아의 자세입니다.'),
                                                                         (834, 'Cervical Cerclage', '자궁목원형묶음술', NULL, '자궁경부 무력증 등으로 인한 조산을 방지하기 위해 자궁목(자궁경부)을 묶어주는 수술입니다.'),
                                                                         (835, 'Cervical Polyp', '자궁목용종, 자궁경부용종', NULL, '자궁의 입구인 자궁목(자궁경부)에 생기는 양성 종양(폴립)입니다.'),
                                                                         (836, 'Cesarean Section', '제왕절개(술)', 'C/S', '산모의 복부와 자궁을 절개하여 태아를 분만하는 수술입니다.'),
                                                                         (837, 'Choriocarcinoma', '융모막암종', NULL, '융모막 세포에서 발생하는 매우 악성도가 높은 종양입니다.'),
                                                                         (838, 'Chorion', '융모막', NULL, '태아를 감싸는 막 중 양막의 바깥쪽에 위치하며, 태반의 일부를 형성합니다.'),
                                                                         (839, 'Chorionic Villus Sampling', '융모막융모검사', 'CVS', '태반의 일부인 융모막 융모 조직을 채취하여 태아의 염색체 이상 등을 진단하는 산전 검사입니다.'),
                                                                         (840, 'Clitoris', '음핵', NULL, '여성의 외부 생식기에 있는 작은 돌출 기관으로, 남성의 음경과 상동기관이며 성적 쾌감에 중요한 역할을 합니다.'),
                                                                         (841, 'Colpopexy', '질고정술', NULL, '질 탈출증 등에서 이완된 질을 주변 조직에 고정시켜주는 수술입니다.'),
                                                                         (842, 'Colposcope', '질확대경 / 질확대경검사', NULL, '자궁경부와 질을 확대하여 관찰하는 기계 / 또는 그 검사 방법을 말합니다.(Colposcopy)'),
                                                                         (843, 'Complete Abortion', '완전유산', NULL, '태아와 태반 조직이 모두 자궁 밖으로 완전히 배출된 상태의 유산입니다.'),
                                                                         (844, 'Contracted Pelvis', '협착골반', NULL, '태아가 통과하기에 골반의 크기가 좁은 상태를 말합니다.'),
                                                                         (845, 'Curettage', '긁어냄(술), 소파술', NULL, '큐렛이라는 기구를 이용해 자궁 내막이나 자궁경부의 조직을 긁어내는 시술입니다.'),
                                                                         (846, 'Dilation and Curettage', '확장과 긁어냄술, 소파술', 'D&C', '자궁경부를 확장시킨 후 자궁내막 조직을 긁어내는 시술로, 진단이나 치료 목적으로 시행됩니다.'),
                                                                         (847, 'Dysmenorrhea', '월경통, 생리통', NULL, '월경(생리) 기간 중에 나타나는 통증입니다.'),
                                                                         (848, 'Eclampsia', '자간증, 경련증', NULL, '임신중독증(전자간증) 산모에게 경련 발작이 동반되는 심각한 상태입니다.'),
                                                                         (849, 'Ectopic Pregnancy', '자궁외임신', NULL, '수정란이 자궁 내막이 아닌 다른 곳(주로 난관)에 착상하여 임신이 진행되는 상태입니다.'),
                                                                         (850, 'Endometrial Cancer', '자궁내막암', NULL, '자궁의 내부를 덮고 있는 자궁내막에 발생하는 악성 종양입니다.'),
                                                                         (851, 'Endometrial Hyperplasia', '자궁내막증식증', NULL, '자궁내막이 비정상적으로 두꺼워지는 상태로, 자궁내막암의 전구 병변이 될 수 있습니다.'),
                                                                         (852, 'Endometriosis', '자궁내막증', NULL, '자궁내막 조직이 자궁이 아닌 다른 부위(난소, 복막 등)에 존재하는 질환입니다.'),
                                                                         (853, 'Endometritis', '자궁내막염', NULL, '자궁내막에 염증이 생긴 상태입니다.'),
                                                                         (854, 'Episiotomy', '회음절개(술)', NULL, '분만 시 질과 항문 사이의 회음부를 절개하여 아기가 나오는 길을 넓혀주는 시술입니다.'),
                                                                         (855, 'Fallopian Tube', '난관, 자궁관', NULL, '난소와 자궁을 연결하는 관으로, 난자의 이동 통로이자 수정이 일어나는 장소입니다.'),
                                                                         (856, 'Fertility', '생식능력 / 수정', NULL, '임신할 수 있는 능력 / 난자와 정자가 결합하여 새로운 개체를 형성하는 과정입니다.(Fertilization'),
                                                                         (857, 'Fetal Distress', '태아곤란증', NULL, '태아의 건강 상태가 나빠져 저산소증 등에 빠진 위험한 상태입니다.'),
                                                                         (858, 'Fetal Heart Rate', '태아심박수', 'FHR', '태아의 심장이 1분 동안 뛰는 횟수입니다.'),
                                                                         (859, 'Fetal Movement', '태아움직임, 태동', NULL, '임신 중 산모가 느끼는 태아의 움직임입니다.'),
                                                                         (860, 'Fetoprotein', '태아단백', 'AFP', '태아의 간에서 생성되는 단백질로, 산모 혈액 검사를 통해 태아의 신경관 결손 등을 선별하는 데 사용됩니다.'),
                                                                         (861, 'Fetoscopy', '태아경검사 / 태아', NULL, '태아경으로 자궁 속 태아를 직접 보는 검사 / 임신 8주 이후의 아기를 말합니다.(Fetus)'),
                                                                         (862, 'Fibroid', '(자궁)근종', NULL, '자궁의 근육층에 생기는 양성 종양으로, 자궁 평활근종과 같은 의미로 쓰입니다.'),
                                                                         (863, 'Forceps Delivery', '겸자분만', NULL, '분만 시 겸자(forceps)라는 기구를 이용해 태아의 머리를 잡고 분만을 돕는 방법입니다.'),
                                                                         (864, 'Fundus of Uterus', '자궁바닥, 자궁저부', NULL, '자궁의 위쪽, 양쪽 난관이 연결되는 부위보다 위에 있는 둥근 부분입니다.'),
                                                                         (865, 'Galactorrhea', '젖흐름증, 유즙분비과다', NULL, '출산과 관련 없이 비정상적으로 유즙이 분비되는 증상입니다.'),
                                                                         (866, 'Gestation', '임신', NULL, '수정란이 자궁에 착상하여 태아가 모체 내에서 발육하는 과정 및 그 기간을 말합니다.'),
                                                                         (867, 'Gestational Diabetes', '임신당뇨', 'GDM', '임신 중 처음 발견되거나 발생한 당뇨병입니다.'),
                                                                         (868, 'Gestational Hypertension', '임신성고혈압', NULL, '임신 20주 이후에 처음으로 혈압이 높아지는 상태입니다.'),
                                                                         (869, 'Gestational Trophoblastic Disease', '임신융모막질환', 'GTD', '태반의 융모막 세포가 비정상적으로 증식하는 질환군을 통칭합니다. (예: 포상기태)'),
                                                                         (870, 'Gravida', '임신부, 임부', NULL, '임신한 여성을 의미합니다.'),
                                                                         (871, 'Gynecology', '부인과학', 'GYN', '여성의 생식기계 질환을 다루는 의학의 한 분야입니다.'),
                                                                         (872, 'Gynecomastia', '여성형유방증', NULL, '남성의 유방이 여성처럼 비정상적으로 발달하는 상태입니다.'),
                                                                         (873, 'Hormone Replacement Therapy', '호르몬대체요법', 'HRT', '폐경 등으로 인해 부족해진 여성호르몬을 외부에서 보충해주는 치료입니다.'),
                                                                         (874, 'Hydatidiform Mole', '포상기태', NULL, '비정상적인 임신으로, 태반의 융모막이 포도송이 모양으로 변하는 질환입니다.'),
                                                                         (875, 'Hymen', '처녀막', NULL, '질 입구를 부분적으로 덮고 있는 얇은 점막 주름입니다.'),
                                                                         (876, 'Hysterectomy', '자궁절제술', NULL, '자궁을 외과적으로 제거하는 수술입니다.'),
                                                                         (877, 'In Vitro Fertilization', '체외수정', 'IVF', '난자와 정자를 체외에서 수정시킨 후 수정란을 여성의 자궁에 이식하는 방법입니다.'),
                                                                         (878, 'Incomplete Abortion', '불완전유산', NULL, '유산 시 태아나 태반 조직의 일부가 자궁 내에 남아있는 상태입니다.'),
                                                                         (879, 'Induced Abortion', '인공유산, 인공임신중절', NULL, '의학적인 방법으로 임신을 종결시키는 것입니다.'),
                                                                         (880, 'Infertility', '불임', NULL, '피임을 하지 않고 정상적인 부부관계를 가졌음에도 1년 이내에 임신이 되지 않는 상태입니다.'),
                                                                         (881, 'Labor', '분만, 진통', NULL, '태아를 만출하는 과정 / 분만 시 동반되는 자궁 수축으로 인한 통증입니다.(Labor Pains)'),
                                                                         (882, 'Last Menstrual Period', '최종월경기', 'LMP', '마지막으로 정상적인 월경을 시작한 날짜로, 분만예정일 계산의 기준이 됩니다.'),
                                                                         (883, 'Leiomyoma', '평활근종', NULL, '평활근(민무늬근)에 생기는 양성 종양으로, 자궁근종이 대표적입니다.'),
                                                                         (884, 'Mammography', '유방조영술', NULL, 'X선을 이용하여 유방을 촬영하는 검사로, 유방암 조기 진단에 사용됩니다.'),
                                                                         (885, 'Mastitis', '유방염', NULL, '유선 조직에 염증이 생긴 상태로, 주로 수유기에 발생합니다.'),
                                                                         (886, 'Meconium Aspiration Syndrome', '태변흡인증후군', 'MAS', '태아가 자궁 내 또는 분만 중 태변(첫 변)에 오염된 양수를 흡입하여 발생하는 호흡곤란 증후군입니다.'),
                                                                         (887, 'Menarche', '초경, 첫월경', NULL, '여성이 처음으로 월경을 시작하는 것을 말합니다.'),
                                                                         (888, 'Menopause', '폐경, 완경', NULL, '여성의 난소 기능이 쇠퇴하여 월경이 영구적으로 멈추는 현상입니다.'),
                                                                         (889, 'Menorrhagia', '월경과다', NULL, '월경 기간이 길어지거나 출혈량이 비정상적으로 많은 상태입니다.'),
                                                                         (890, 'Metrorrhagia', '자궁출혈', NULL, '월경 기간이 아닌데도 발생하는 불규칙적인 자궁 출혈입니다.'),
                                                                         (891, 'Missed Abortion', '계류유산', NULL, '태아가 자궁 내에서 사망했지만 자궁 밖으로 배출되지 않고 남아있는 상태의 유산입니다.'),
                                                                         (892, 'Multipara', '다산부, 다분만부', NULL, '2번 이상 출산 경험이 있는 여성을 말합니다.'),
                                                                         (893, 'Myomectomy', '근종적출술', NULL, '자궁을 보존하면서 자궁근종만 제거하는 수술입니다.'),
                                                                         (894, 'Neonatal Icterus', '신생아황달', NULL, '출생 후 신생아에게 나타나는 황달로, 대부분은 생리적인 현상입니다.'),
                                                                         (895, 'Newborn', '신생아', NULL, '출생 후 4주(28일)까지의 아기를 말합니다.'),
                                                                         (896, 'Obstetrics', '산과, 산과학', 'OB', '임신, 출산, 산욕기를 다루는 의학의 한 분야입니다.'),
                                                                         (897, 'Oligohydramnios', '양수과소증', NULL, '임신 주수에 비해 양수의 양이 비정상적으로 적은 상태입니다.'),
                                                                         (898, 'Oligomenorrhea', '희발월경', NULL, '월경 주기가 35일 이상으로 비정상적으로 긴 상태입니다.'),
                                                                         (899, 'Oocyte', '난모세포 / 난자', NULL, '난모세포는 감수분열을 통해 성숙한 생식세포인 난자가 됩니다.(Ovum)'),
                                                                         (900, 'Oophorectomy', '난소절제술', NULL, '한쪽 또는 양쪽 난소를 외과적으로 제거하는 수술입니다.');
INSERT INTO terms (id, spelling, meaning, abbreviation, explanation) VALUES
                                                                         (901, 'Oophoritis', '난소염', NULL, '난소에 염증이 생긴 상태입니다.'),
                                                                         (902, 'Ovarian Cyst', '난소낭종, 난소물혹', NULL, '난소에 액체가 차 있는 주머니 모양의 혹이 생긴 상태입니다.'),
                                                                         (903, 'Ovarian Tumor', '난소종양', NULL, '난소에 발생하는 모든 종류의 종양(양성, 악성)을 말합니다.'),
                                                                         (904, 'Ovaries', '난소', NULL, '여성의 골반 내에 있는 한 쌍의 생식 기관으로, 난자를 생성하고 여성호르몬을 분비합니다.'),
                                                                         (905, 'Parturition', '분만, 출산', NULL, '임신이 끝나고 태아와 부속물이 모체 밖으로 배출되는 과정입니다.'),
                                                                         (906, 'Pelvic Examination', '골반검사, 내진', NULL, '의사가 손이나 기구를 이용해 여성의 질, 자궁, 난소 등의 상태를 진찰하는 것입니다.'),
                                                                         (907, 'Pelvic Inflammatory Disease', '골반염증질환', 'PID', '자궁, 난관, 난소 등 여성의 상부 생식 기관에 염증이 발생한 질환을 통칭합니다.'),
                                                                         (908, 'Pelvic Organ Prolapse', '골반장기탈출(증)', 'POP', '자궁, 방광, 직장 등의 골반 장기가 아래로 처지거나 질 밖으로 빠져나오는 상태입니다.'),
                                                                         (909, 'Pelvis', '골반 / 골반측정법', NULL, '몸통의 아랫부분을 형성하는 뼈 구조물 / 분만을 위해 골반의 크기를 측정하는 방법입니다.(Pelvimetry)'),
                                                                         (910, 'Perineal Region', '샅부위, 회음부', NULL, '여성의 질 입구와 항문 사이, 남성의 음낭과 항문 사이의 부위입니다.'),
                                                                         (911, 'Placenta Accreta', '유착/침윤/관통 태반', NULL, '태반이 자궁벽에 비정상적으로 깊게 유착된 상태로, 유착 깊이에 따라 구분됩니다.(Increta / Percreta)'),
                                                                         (912, 'Placenta Previa', '전치태반', NULL, '태반이 자궁의 출구(자궁경부)를 덮고 있거나 매우 가까이 위치한 상태입니다.'),
                                                                         (913, 'Polycystic Ovarian Syndrome', '다낭난소증후군', 'PCOS', '여러 개의 작은 난포가 발달하지만 배란이 잘 되지 않아 무월경, 불임 등을 유발하는 내분비 질환입니다.'),
                                                                         (914, 'Polyhydramnios', '양수과다증', NULL, '임신 주수에 비해 양수의 양이 비정상적으로 많은 상태입니다.'),
                                                                         (915, 'Polymenorrhea', '빈발월경', NULL, '월경 주기가 21일 미만으로 비정상적으로 짧은 상태입니다.'),
                                                                         (916, 'Postmenopausal Period', '폐경후기', NULL, '마지막 월경 이후의 삶의 기간을 말합니다.'),
                                                                         (917, 'Postpartum Depression', '산후우울증', NULL, '출산 후 발생하는 우울증으로, 단순한 우울감보다 심하고 오래 지속됩니다.'),
                                                                         (918, 'Postpartum Hemorrhage', '산후출혈', 'PPH', '분만 후 과도한 출혈이 발생하는 응급 상황입니다.'),
                                                                         (919, 'Pregnancy', '임신', NULL, '수정란이 자궁에 착상하여 태아가 모체 내에서 발육하는 과정 및 그 기간을 말합니다.'),
                                                                         (920, 'Premature Rupture of Membrane', '조기양막파수, 조기양막파열', 'PROM', '진통이 시작되기 전에 양막이 파열되어 양수가 흐르는 상태입니다.'),
                                                                         (921, 'Preterm Delivery', '조기분만 / 조기진통', NULL, '임신 37주 이전에 분만하는 것 / 또는 진통이 시작되는 것입니다.(Labor)'),
                                                                         (922, 'Primigravida', '초임부 / 초산부', NULL, '처음 임신한 여성 / 처음 분만한 여성을 말합니다.(Primipara)'),
                                                                         (923, 'Puerperal Fever', '산욕열 / 산욕감염', NULL, '분만 후 산욕기에 발생하는 감염으로 인한 고열 증상 / 또는 그 감염 자체를 말합니다.(Infection)'),
                                                                         (924, 'Puerperium', '산욕기', NULL, '분만 후 산모의 몸이 임신 전 상태로 회복되는 기간으로, 보통 6~8주입니다.(Puerperal Period)'),
                                                                         (925, 'Salpingectomy', '자궁관절제술, 난관절제술', NULL, '한쪽 또는 양쪽 자궁관(난관)을 외과적으로 제거하는 수술입니다.'),
                                                                         (926, 'Salpingitis', '자궁관염, 난관염', NULL, '자궁관(난관)에 염증이 생긴 상태입니다.'),
                                                                         (927, 'Spontaneous Abortion', '자연유산', NULL, '의학적 시술 없이 임신 20주 이전에 임신이 종결되는 것입니다.'),
                                                                         (928, 'Sterilization', '불임(술)', NULL, '수술 등을 통해 영구적으로 임신이 불가능하게 만드는 것입니다.'),
                                                                         (929, 'Threatened Abortion', '절박유산', NULL, '임신 초기에 출혈이나 복통이 있어 유산의 가능성이 높은 상태이지만, 아직 유산이 진행되지는 않은 상태입니다.'),
                                                                         (930, 'Total Abdominal Hysterectomy', '복식전체자궁절제술', 'TAH', '복부를 절개하여 자궁 전체(자궁경부 포함)를 제거하는 수술입니다.'),
                                                                         (931, 'Tubal Ligation', '자궁관묶기, 난관결찰', NULL, '여성의 난관(자궁관)을 묶거나 잘라서 난자와 정자가 만나는 것을 막는 영구 피임 수술입니다.'),
                                                                         (932, 'Uterine Cervix', '자궁목, 자궁경부', NULL, '자궁의 아래쪽, 질과 연결되는 좁은 부분입니다.'),
                                                                         (933, 'Uterine Contraction', '자궁수축', NULL, '분만 시 태아를 밀어내거나 평상시 월경혈을 배출하기 위해 자궁 근육이 수축하는 현상입니다.'),
                                                                         (934, 'Uterine Myoma', '자궁근종', NULL, '자궁의 근육층에 발생하는 가장 흔한 양성 종양입니다.'),
                                                                         (935, 'Uterine Polyp', '자궁용종', NULL, '자궁 내막이나 자궁경부에 생기는 양성 종양(폴립)입니다.'),
                                                                         (936, 'Uterine Tube', '자궁관, 난관', NULL, '난소와 자궁을 연결하는 관으로, 난자의 이동 통로이자 수정이 일어나는 장소입니다.'),
                                                                         (937, 'Uterus', '자궁', NULL, '여성의 골반 내에 있는 근육질 기관으로, 수정란이 착상하여 태아가 자라는 곳입니다.'),
                                                                         (938, 'Vacuum Extraction', '흡입분만', NULL, '분만 시 진공 흡착 컵을 태아의 머리에 부착하여 분만을 돕는 방법입니다.'),
                                                                         (939, 'Vaginal Canal', '질', NULL, '자궁경부와 외부 생식기를 연결하는 관 모양의 기관입니다.(Vagina)'),
                                                                         (940, 'Vaginal Delivery', '질식분만, 자연분만', NULL, '제왕절개를 하지 않고 질을 통해 태아를 분만하는 것입니다.'),
                                                                         (941, 'Vaginal Discharge', '질분비물', NULL, '질에서 나오는 분비물을 통칭하며, 정상적이거나 감염의 징후일 수 있습니다.'),
                                                                         (942, 'Vaginal Examination', '질검사, 내진', NULL, '의사가 손가락이나 기구를 이용해 질과 자궁경부의 상태를 진찰하는 것입니다.'),
                                                                         (943, 'Vaginal Suppository', '질좌제 / 질정', NULL, '질 내에 직접 삽입하여 약효를 내는 고형 제제입니다.(Tablet)'),
                                                                         (944, 'Vaginismus', '질경련 / 질염', NULL, '성교나 내진 시 질 근육이 불수의적으로 강하게 수축하는 것 / 질에 염증이 생긴 상태입니다.(Vaginitis)'),
                                                                         (945, 'Vaginoplasty', '질성형술', NULL, '질의 모양이나 기능을 개선하기 위해 시행하는 수술입니다.'),
                                                                         (946, 'Vulva', '음문, 외음부', NULL, '여성의 외부 생식기를 통칭하는 용어입니다. (대음순, 소음순, 음핵 등 포함)'),
                                                                         (947, 'Vulvectomy', '음문절제술, 외음부절제술', NULL, '여성의 외부 생식기인 음문을 외과적으로 제거하는 수술입니다.'),
                                                                         (948, 'vomiting', '구토', NULL, '구토는 위 내용물을 입으로 강하게 배출하는 행위.');
